insert into public.mushroom_growth_conditions (slug,best_after,soil_conditions,microhabitat,foraging_difficulty,foraging_tips,source,verified) values
('agaricus_augustus','Sommerpilz, Hauptzeit Juli-September (in Mitteleuropa Juni-Oktober). Schiebt oft schubartig nach längerer Trocken-/Hitzephase, wenn ergiebiger Regen einsetzt - dann erscheinen die Fruchtkörper innerhalb weniger Tage fast explosiv in grösserer Zahl.',NULL,'Park- und Waldbewohner. Am häufigsten an Fichtenwald- und Forsträndern, lichte Stellen, Wegränder, Böschungen; gern bei Fichte und Eiche, seltener im Laubwald. Auch in Parks und Gärten.','mittel',NULL,'Recherche-Angabe geprüft (mykologisch plausibel, unverändert übernommen)','t'),
('agaricus_campestris','Wärmeliebend; fruchtet ab Juli (Saison Mai-Oktober) vor allem in trocken-warmen Sommern nach ergiebigem Regen. Typisch erscheinen die Fruchtkörper ca. 7-10 Tage nach kräftigem Niederschlag, dann oft massenhaft in Gruppen, Reihen oder Hexenringen.',NULL,'Offenes Grünland: Wiesen, Weiden (gern beweidet/gedüngt), Felder, Gärten und Parks. Kein Waldpilz - direkt im Gras, oft in Hexenringen.','anfaenger',NULL,'Recherche-Angabe geprüft (mykologisch plausibel, unverändert übernommen)','t'),
('agaricus_silvaticus','Hauptzeit Aug–Okt, schubweise ca. 5–10 Tage nach ergiebigem Regen bei milden 10–16 °C; erscheint oft truppweise und kann nach jedem Regenschub neu nachwachsen.','Bevorzugt frische bis feuchte, eher saure, humus- und nadelstreureiche Waldböden; meidet stark kalkige Standorte.','Streu- und Humuszersetzer (saprobiontisch, keine Mykorrhiza), typisch im Nadelstreu unter Fichten, auch in Misch- und Bergwäldern; oft bei Moos und Fichtennadel-Polstern.','mittel','Bräunlich-faserig geschuppter Hut, Fleisch und Lamellen-Region röten beim Anschneiden/Reiben deutlich (Schnittprobe wichtig). Geruch angenehm pilzig, NICHT chemisch/tintig. Sicheres Ausschlusskriterium: keine Knolle mit häutiger Scheide am Stielgrund – sonst Verwechslungsgefahr mit jungen, tödlichen Amanita (Knollenblätterpilz) prüfen. Gelb anlaufende, karbolartig riechende Champignons (A. xanthodermus) meiden.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)','f'),
('agaricus_silvicola','Hauptzeit Aug–Okt (bis Nov in milden Lagen), schubweise rund 1 Woche nach kräftigem Regen bei 10–16 °C; einzeln bis in kleinen Gruppen.','Frische, humose Waldböden, kalkmeidend bis neutral; in nährstoffreicher Nadel- und Laubstreu.','Saprobiontischer Streuzersetzer (keine Mykorrhiza), gern im Nadelstreu unter Fichten sowie in Mischwäldern; Standorttyp: krautarmer, schattiger Waldboden.','experte','Weisslich-cremiger, schlanker Hut, gilbt bei Druck/Reibung leicht goldgelb; deutlicher Anis-/Bittermandel-Geruch. Lamellen jung blass-rosa, später schokobraun – NIE weiss bleibend. WICHTIG: weisse, weisslamellige Verwechslung mit tödlichem Weissen Knollenblätterpilz (Amanita) – immer auf Stielbasis ohne häutige Scheide/Knolle und auf rosa-braune Lamellen achten. Karbolartiger Geruch + chromgelbes Anlaufen an der Stielbasis = giftiger Karbol-Egerling, meiden.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)','f'),
('albatrellus_confluens','Sommer bis Herbst, Hauptzeit etwa August-Oktober (Quellen nennen Juni-November). Fruchtet bodenständig nach feuchten Phasen im Nadelwald.',NULL,'Nadelwald-Pilz, wächst am Boden (nicht am Holz) gesellig bei Nadelbäumen - je nach Quelle bei Fichte und/oder Kiefer; oft auf Lichtungen, an Waldwegen oder Bergwiesenrändern. Häufig in verschmelzenden Büscheln mit überlappenden Hüten.','experte',NULL,'Recherche-Angabe geprüft via WebSearch (Mykorrhiza Fichte/Kiefer + Saison Jul-Okt bestätigt; unverändert übernommen)','t'),
('amanita_battarrae','Sommer bis Herbst, Hauptzeit Juli-Oktober. Erscheint einzeln bis gesellig nach durchdringenden Sommer- und Frühherbstregen, sobald der Boden in montanen Lagen wieder durchfeuchtet ist; meist 1-2 Wochen nach ergiebigem Niederschlag in warm-feuchten Phasen.','Saure, nährstoffarme Wald- und Rohhumusböden; bevorzugt bodensauer-montane Standorte, oft an mit Moosen und Heidelbeere bestandenen Stellen.','Mykorrhiza-Partner: Symbiont von Fichte, Buche, Birke und Kiefer in Nadel-, Misch- und Laubwald, vor allem in höheren, montanen Lagen. Wächst am Boden, gern an Wegrändern, Böschungen und in lichten, moosigen Waldpartien.','experte','Scheidenstreifling ohne Stielring und ohne Knolle, mit häutiger Scheide an der Stielbasis und stark gerieftem Hutrand; kennzeichnend ist der zweifarbige, oliv-graubraune Hut mit dunklerer Mitte. NUR gut durcherhitzt essbar - roh giftig. Verwechslungsgefahr mit tödlich giftigen Knollenblätterpilzen (Amanita phalloides/virosa) und dem Pantherpilz, besonders im jungen Ei-Stadium: jeden Fund komplett ausgraben, auf Ring/Knolle/Lamellen prüfen. Nur für sehr erfahrene Sammler mit sicherer Amanita-Kenntnis.','Recherche geprüft via WebSearch (123pilzsuche, pilzbuch-pilzwelten, Wikipedia): Amanita vaginata-Gruppe, Mykorrhiza Fichte/Buche/Birke, saure montane Böden, roh giftig + Amanita-Verwechslung bestätigt.','f'),
('amanita_caesarea','Hauptzeit Jul–Okt nach sommerlichen Gewitterregen, ca. 1–2 Wochen nach Niederschlag bei warmen 18–25 °C; wärmebedürftig, in der Schweiz selten und nur an wenigen wärmebegünstigten Südlagen (Tessin/Südalpen).','Eher trockene bis frische, saure bis schwach kalkige, durchlässige Böden in wärmebegünstigten Lagen.','Mykorrhiza mit Eiche, Edelkastanie, selten Buche/Kiefer; lichte, warme Laub-/Kastanienwälder, Hangwälder mit guter Besonnung.','experte','Leuchtend orange-roter Hut, dottergelbe (nicht weisse!) Lamellen und gelber Stiel mit gelbem, häutigem Ring – plus weisse, sackartige Volva am Stielgrund. ACHTUNG Eistadium: junge, im weissen Hüllei steckende Exemplare sind kaum vom tödlichen Grünen Knollenblätterpilz oder vom Fliegenpilz zu unterscheiden – nie unreife „Eier“ sammeln. In der Schweiz vielerorts geschützt/selten – Bestand schonen. Nur bei voll aufgeschirmtem, eindeutig gelbem Lamellen-/Stielbild ernten.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)','f'),
('amanita_crocea','Hauptzeit Jul–Okt (vereinzelt ab Jun und bis Nov), ca. 1–2 Wochen nach ergiebigem Regen bei 12–18 °C; erscheint schubweise einzeln bis in kleinen Gruppen.','Bevorzugt saure, eher feuchte Wald- und Moorrandböden; auch auf sandig-humosen Standorten, kalkmeidend.','Mykorrhiza vor allem mit Birke, daneben Eiche, Erle, Hainbuche, Hasel und Fichte; in Laub-, Misch- und Nadelwäldern, gern an feuchten, moosigen Stellen.','experte','Orange-ockerfarbener, ungeriefter-mittiger Hut mit deutlich gerieftem Rand, KEIN Ring am glatten, orange genatterten Stiel, weisse, hohe, oft orange überlaufene Scheide (Volva) am Grund. Roh giftig – nur gut durchgegart geniessbar (bedingt essbar). Da Gattung Amanita: tödliche Knollenblätterpilze haben einen Ring – ringloser Streifling mit gerieftem Hutrand und Volva ist Bestimmungsschlüssel. Im Zweifel nicht sammeln; Volva immer vollständig ausgraben.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)','f'),
('amanita_fulva','Hauptzeit Jul–Okt (ab Jun möglich), ca. 1–2 Wochen nach ergiebigem Regen bei 12–18 °C; einer der häufigsten Streiflinge, erscheint schubweise.','Saure, feuchte Böden, oft an Moorrändern und in feuchten Nadel-/Mischwäldern; kalkmeidend.','Mykorrhiza mit Birke, Buche, Eiche, Fichte und Kiefer; in Laub-, Misch- und Nadelwald sowie Moorgebieten, gern an feuchten, moosigen Plätzen.','experte','Rotbrauner bis fuchsbrauner Hut mit deutlich gerieftem Rand, glatter, ringloser, blass rötlichbrauner Stiel, hohe weisse, oft rostbraun gefleckte Scheide (Volva) am Grund. Roh giftig – nur gut durchgegart geniessbar. Gattung Amanita: ringlos + gerieft + Volva unterscheidet vom tödlichen, beringten Knollenblätterpilz. Stielbasis stets komplett ausgraben, um die Volva zu prüfen; im Zweifel stehen lassen.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)','f'),
('amanita_rubescens','Wenig wählerisch; Fruchtkörper von Juni bis Oktober (bei milder Witterung bis Dezember), einzeln bis gesellig. Erscheint zuverlässig nach feuchten Phasen über die ganze Pilzsaison verteilt - einer der ersten und am längsten erscheinenden Sommer-/Herbstpilze.',NULL,'Mykorrhiza mit vielen Baumarten (Fichte, Tanne, Kiefer, Buche, Eiche). In Nadel-, Laub- und Mischwäldern, auch Parks und Gärten; oft an Waldwegen und lichten Stellen.','anfaenger',NULL,'Recherche-Angabe geprüft (mykologisch plausibel, unverändert übernommen)','t'),
('amanita_strobiliformis','Hauptzeit Jul–Okt nach warmen Sommerregen, ca. 1–2 Wochen nach Niederschlag bei warmen 16–22 °C; wärmeliebend, einzeln stehend.','Bevorzugt kalkreiche, basenreiche, eher trocken-warme Böden; auf Kalk und in nährstoffreichen Parkböden.','Mykorrhiza mit Eiche, Buche, Linde, selten Kiefer; in wärmebegünstigten Laubwäldern, Parkanlagen, an Weg- und Waldrändern auf Kalk.','experte','Grosser, weisslicher Hut mit groben, pyramidalen, leicht abwischbaren grauweissen Hüllflocken, beringter Stiel mit knolliger, von gürtelartigen Flockenresten umgebener Basis (keine häutige Scheide). Bedingt essbar – minderwertig und wegen Verwechslungsgefahr in der Gattung Amanita nur für Kenner. Sicher abgrenzen gegen den giftigen Pantherpilz und den Fliegenpilz; bei flockigem weissem Wulstling im Zweifel grundsätzlich stehen lassen.','123pilze; DGfM; SwissFungi (Datenbank Schweiz); gängige Pilzführer (Laux, Gerhardt)','f'),
('amanita_submembranacea','Spätsommer bis Herbst, Hauptzeit August-Oktober (mit erster Welle teils ab Mai/Juni). Fruchtet nach feuchten Phasen im montanen Nadel- und Mischwald, typisch einige Tage bis zwei Wochen nach kräftigem Regen in der zweiten Sommerhälfte.','Saure, basenarme Böden montaner Nadelwälder; gern auf Rohhumus, moosigem Untergrund und an Moorrändern.','Mykorrhiza-Partner: Symbiont von Fichte, Tanne, Kiefer und Birke, vor allem in montanen Nadel- und Mischwäldern auf sauren Böden. Wächst bodenständig, oft an feuchteren, moosreichen Stellen und Moorrändern.','experte','Graubraun-olivlicher Scheidenstreifling mit grauen Velumflocken auf dem Hut, häutig-grauer Scheide und stark gerieftem Hutrand; kein Ring, keine Knolle. NUR gut gekocht essbar - roh giftig. Wegen der Zugehörigkeit zu Amanita hohe Verwechslungsgefahr mit tödlichen Knollenblätterpilzen und dem Pantherpilz, vor allem im Ei-Stadium: stets vollständig ausgraben und Stielbasis prüfen. Nur für Sammler mit sicherer Gattungskenntnis.','Recherche geprüft via WebSearch (Wikipedia, fundkorb, pilzbuch-pilzwelten): Mykorrhiza Fichte/Tanne/Kiefer/Birke, saure montane Böden, Saison Spätsommer-Herbst, Amanita-Verwechslung bestätigt.','f'),
('amanita_vaginata','Hauptzeit Juni–Oktober, oft schon im Frühsommer; erscheint einzeln und schubweise rund 1–2 Wochen nach kräftigem Regen bei milden 14–20 °C. Verträgt wärmere, trockenere Phasen besser als viele andere Streiflinge und kommt nach Sommergewittern rasch.','Wächst auf eher sauren bis neutralen, mässig frischen Böden; toleriert auch sandige und nährstoffärmere Standorte. Mag mässige Bodenfeuchte, keine Staunässe.','Mykorrhiza-Partner mit Laub- und Nadelbäumen – v. a. Birke, Buche, Eiche, Fichte und Kiefer; auch an Waldrändern, in Parks und unter eingestreuten Bäumen. Zeigerbäume: Birke und Buche auf sauren Böden.','experte','Nur roh giftig, gegart bedingt essbar – wegen Zugehörigkeit zur kritischen Gattung Amanita ausschliesslich für Erfahrene. Kennzeichen: grauer, am Rand deutlich gerillter ("gestreifter") Hut, KEIN Ring am Stiel, dafür eine häutige, weisse Scheide (Volva) am Stielgrund – immer komplett ausgraben und die Stielbasis prüfen. Lebensgefährliche Verwechslung mit jungen Knollenblätterpilzen (Amanita) und grauen Wulstlingen ausschliessen; im Zweifel stehen lassen.','123pilze, DGfM, Pilzführer Schweiz (SwissFungi)','f'),
('apioperdon_pyriforme','Sommer bis Spätherbst, Hauptzeit Juli-November. Erscheint büschelig in grosser Zahl nach feuchten Perioden auf Totholz, oft schubartig wenige Tage nach ergiebigem Regen; verträgt die feuchte Herbstwitterung gut und fruchtet bis zu den ersten Frösten.','Wächst nicht am Boden, sondern auf Holz: morsche Laubholz- und Nadelholzstümpfe, Strünke, liegende Stämme und vergrabenes Holz/Holzmulch.','Saprobiont (Holzzersetzer) - der einzige regelmässig auf Holz wachsende Stäubling. Dicht büschelig auf morschen Stümpfen und Strünken in Wäldern, Parks und an Wegrändern; birnenförmige Fruchtkörper mit wurzelartigen weissen Myzelsträngen an der Basis.','experte','Nur ganz jung essbar, solange das Fleisch innen rein schneeweiss ist; bei gelb-bräunlicher oder olivlicher Verfärbung ungeniessbar. PFLICHT: jeden Fruchtkörper längs aufschneiden - tödlich giftige junge Knollenblätterpilze (Amanita) sehen als Ei kugelig aus, zeigen im Schnitt aber Hut-/Lamellenanlagen, der Stäubling ist innen homogen weiss. Büscheliges Wachstum auf Holz und wurzelartige Stränge an der Basis grenzen ihn vom Flaschenstäubling ab. Wegen des Amanita-Ei-Risikos Sammeln nur mit Schnittkontrolle - Anfänger-untauglich.','Recherche geprüft via WebSearch (Wikipedia, 123pilzsuche, pilzbuch-pilzwelten): einziger Holz-Stäubling, jung weissfleischig essbar, Amanita-Ei-Verwechslung + Pflicht-Längsschnitt bestätigt.','f'),
('auricularia_auricula_judae','Ganzjährig, Hauptsaison November-März (frisch gut sammelbar August-April). Bildet Fruchtkörper immer dann, wenn ausreichend Feuchtigkeit da ist - besonders ergiebig nach längeren Regenphasen; gedeiht bei milden, feuchten Temperaturen und ist frostresistent.',NULL,'Vor allem an geschwächtem oder totem Holunder, häufig auch an Buche; daneben Birke, Ulme, Ahorn u.a. Laubholz, sehr selten Nadelholz. An morschen Ästen, Stämmen und Totholz in feuchten Gebüschen, Auwäldern, Hecken.','anfaenger',NULL,'Recherche-Angabe geprüft (mykologisch plausibel, unverändert übernommen)','t'),
('austernpilz','Spätherbst- bis Winterpilz; Hauptzeit etwa Mitte November bis Mitte Januar, frisch bis ins Frühjahr. Die heimische Form (Winterauster) fruchtet erst nach einem Kältereiz/Temperatursturz unter ~10°C (''Cold Shock''); wächst auch an frostfreien Wintertagen langsam weiter.',NULL,'Büschelig an totem Laubholz - vor allem Buche, auch andere Laubbäume; selten Nadelholz. An Stümpfen, liegenden Stämmen und an Wunden/Verletzungen lebender Bäume, oft auch hoch oben am Stamm.','mittel',NULL,'Recherche-Angabe geprüft (mykologisch plausibel, unverändert übernommen)','t'),
('boletus_aereus','Wärmeliebend - fruchtet nur in warmen Sommern; Saison etwa Juli-Oktober (manche Quellen ab Mai). Erscheint nach warmen Gewitterregen in der warmen Jahreszeit; profitiert vom Klimawandel und breitet sich nordwärts aus.',NULL,'Mykorrhiza mit Laubbäumen, am häufigsten Eiche, auch Edelkastanie, Buche und Hagebuche. In warmen, lichten, älteren Eichen-, Buchen- oder Mischwäldern, an südexponierten Hängen und Waldrändern, auch in Parks.','experte',NULL,'Recherche-Angabe geprüft via WebSearch (Eiche/Buche-Mykorrhiza + warmliebend Jul-Okt bestätigt; unverändert übernommen)','t'),
('boletus_pinophilus','Zweigipflige Saison: ein erster Schub im Früh-/Hochsommer (Juni–Juli) und ein Hauptschub im Herbst (September–Oktober); erscheint typischerweise 1–2 Wochen nach ergiebigem Regen bei Bodentemperaturen um 12–18 °C. In Bergwäldern oft etwas später als der Gemeine Steinpilz.','Bevorzugt nährstoffarme, saure bis neutrale, sandige und gut drainierte Böden; trockene bis mässig frische Standorte, keine Staunässe.','Mykorrhiza-Partner v. a. mit Kiefer (Pinus), selten Fichte; in Kiefern- und Bergnadelwäldern, gern auf höheren Lagen. Zeigerstandort: lichte Kiefernbestände auf Sand, oft am Wegrand und an grasigen Lichtungen.','mittel','Hervorragender Speisepilz, Verwechslungsrisiko gering, aber Steinpilz-Sicherheit nötig. Erkennung: rotbraun-kupferfarbener, oft fein bereifter Hut, weisses unveränderliches Röhrenlager (jung weiss, später gelbgrün), heller netziger Stiel; Fleisch bleibt beim Schnitt weiss. Abgrenzung zum bitteren Gallenröhrling (rosa Röhren, bitterer Geschmack – Kostprobe an der Röhrenspitze) und zum blau anlaufenden Hexenröhrling beachten.','123pilze, SwissFungi, Pilzführer Schweiz','f'),
('boletus_reticulatus','Frühe Sommerart: Hauptschub Juni–Juli, in milden Lagen schon ab Mai bis in den Oktober. Fruchtet 1–2 Wochen nach ergiebigem Sommerregen bei warmem, schwülem Wetter (rund 15–20°C). Reagiert schneller auf Sommergewitter als der Herbst-Steinpilz.',NULL,'Mykorrhiza-Partner sind Laubbäume: Eiche, Buche, Linde, auch Edelkastanie. Nur in Laub- und Laub-Nadel-Mischwäldern, nie im reinen Nadelwald. Gezielt an lichten, sonnigen Stellen suchen: Waldränder, Wegränder, grasige Lichtungen, Hangkanten in Eichen-/Buchenbeständen.','mittel',NULL,'Faktencheck bestätigt (WebSearch: Wikipedia, Fungiversum, Pilzkurse Schweiz) — Saison Sommer + Laubbaum-Mykorrhiza korrekt, unverändert übernommen.','t'),
('bovista_plumbea','Sommer bis Herbst, Hauptzeit Juni-Oktober. Fruchtet auf kurzgrasigen Wiesen und Weiden nach Regen in warmen Perioden, oft einige Tage nach ergiebigem Niederschlag; die kleinen Fruchtkörper erscheinen gesellig im niedrigen Gras.','Nährstoffarme bis mässig gedüngte Wiesen- und Weideböden; bevorzugt kurzrasige, sonnige Magerrasen und Rasenflächen.','Saprobiont auf Grünland - kein Wald-/Mykorrhizapilz. Auf Wiesen, Weiden, Rasen und Magerrasen im kurzen Gras; kleiner Bovist, der zur Reife mit dem Substrat nur locker verbunden ist und vom Wind verfrachtet werden kann.','experte','Nur ganz jung essbar, wenn das Innere komplett rein weiss und fest ist; bei einsetzender olivgrauer Sporenreife ungeniessbar. PFLICHT: jeden kugeligen Fruchtkörper längs durchschneiden - junge tödliche Knollenblätterpilze (Amanita) können ebenfalls kugelig erscheinen, zeigen im Schnitt aber Lamellen-/Hutanlagen. Nur völlig homogen-weisses Innenfleisch ohne jede Struktur ist unbedenklich. Wegen des Amanita-Ei-Risikos nur mit konsequenter Schnittkontrolle - nicht für Anfänger.','Recherche geprüft via WebSearch (123pilzsuche, Tintling, Fundkorb, Wikipedia): Grünland-Saprobiont, jung weissfleischig essbar, Pflicht-Längsschnitt wegen Amanita-Ei bestätigt.','f'),
('butterpilz','Spätsommer bis Spätherbst, Hauptzeit August–November (in warmen Jahren ab Juni/Juli). Fruchtet schubweise rund 1–2 Wochen nach Regenphasen bei mild-feuchtem Wetter; einer der zuverlässigsten Pilze nach Herbstregen.',NULL,'Mykorrhiza streng an Kiefer (Pinus) gebunden, v.a. junge Kiefern. In Nadel- und Mischwäldern, jungen Kiefernforsten, Aufforstungen. Gezielt an Wegrändern, Böschungen, Lichtungen und grasigen Schneisen mit jungen Kiefern suchen.','anfaenger',NULL,'Faktencheck bestätigt (WebSearch: AWL.ch, Pilzkurse Schweiz, fungifriends) — Kiefer-Mykorrhiza exklusiv + Spätsommer/Herbst korrekt, unverändert übernommen.','t'),
('butyriboletus_appendiculatus','Wärmeliebende Sommerart: Hauptzeit Juli–September (vereinzelt ab Juni), nach warmen Sommergewittern rund 1–2 Wochen verzögert; braucht warme Böden über ~16 °C und erscheint in trocken-warmen Sommern oft früher als andere Röhrlinge.','Wächst bevorzugt auf warmen, basischen bis kalkreichen, eher frischen Böden in Tief- und Hügellagen; meidet stark saure, kalte Standorte.','Mykorrhiza-Partner mit Laubbäumen, v. a. Eiche (Quercus) und Buche (Fagus); in lichten, warmen Eichen-/Buchenwäldern und an deren Rändern. Zeigerstandort: thermophile Kalk-Laubwälder, oft an krautreichen Hängen.','experte','Guter Speisepilz, aber sichere Abgrenzung innerhalb der Dickröhrlinge nötig. Merkmale: hell ocker- bis semmelfarbener Hut, leuchtend gelbe Röhren und gelbes Fleisch, das nur schwach bläulich anläuft, feines gelbes Stielnetz, oft "angehängte" wurzelartige Stielbasis (Namensgeber). Strikt vom giftigen Satansröhrling (rote Poren, weisslicher Hut, kalkliebend, gleicher Standort!) und anderen rotporigen Dickröhrlingen trennen – nur Exemplare mit gelben Poren nehmen.','123pilze, DGfM, SwissFungi','f'),
('calocybe_gambosa','Frühjahrs-/Frühsommerart: April bis Juli, namensgebend rund um den St.-Georgs-Tag (23. April) bis Mai, oft in zwei Schüben (Ende April–Mitte Mai, dann Juni–Anfang Juli). Höhenabhängig — in den Bergen später. Fruchtet nach milder, feuchter Frühlingswitterung.',NULL,'Sonnige, grasige Stellen an Waldrändern, Hecken (Prunetalia-Schlehenhecken), Haselgebüsch, Wiesen und in lichten Buchen-/Buchen-Tannenwäldern und Auwäldern. Oft entlang von Hecken- und Wegrändern. Wächst gesellig in Trupps, Bögen und breiten Hexenringen.','mittel',NULL,'Faktencheck bestätigt (WebSearch: First-Nature, Pilzseite, Foraging Course Co.) — Frühjahrs-/Mai-Saison (NICHT Herbst) + Hecken/Wiesen-Habitat korrekt, unverändert übernommen.','t'),
('calvatia_gigantea','Spätsommer bis Herbst, Hauptzeit Juli–Oktober. Erscheint nach warmen, feuchten Phasen, oft einige Tage nach kräftigem Sommer-/Herbstregen. Schiesst dann schnell zu grossen Fruchtkörpern auf.',NULL,'Kein Mykorrhiza-Partner — wächst auf offenen Flächen: Fett-/Viehweiden, gedüngte Wiesen, frisch gemähte Wiesen, Wegränder, Gärten, Parks, auch lichte Waldränder und Brennnessel-/Hochstaudenfluren. Standorttreu, oft jahrelang am selben Platz.','mittel',NULL,'Faktencheck bestätigt (WebSearch: Wikipedia, Tintling, Fundkorb) — Saprobiont (kein Mykorrhiza) + Sommer–Herbst auf Weiden/Wiesen korrekt, unverändert übernommen.','t'),
('calvatia_utriformis','Sommer bis Herbst, Hauptzeit Juni-Oktober. Erscheint einzeln bis gesellig auf Wiesen und Magerrasen nach durchgreifenden Regenfällen in warmen Phasen, oft rund eine Woche nach ergiebigem Niederschlag; auch in subalpinen Matten.','Magere, basenarme bis mässig nährstoffreiche Wiesen-, Weide- und Heideböden; bevorzugt kurzrasige, offene Magerrasen, auch in höheren Lagen.','Saprobiont auf Offenland - kein Mykorrhizapilz. Auf Wiesen, Weiden, Magerrasen, Heiden und subalpinen Matten; grosser, beutel- bis kreiselförmiger Stäubling mit verjüngter Stielbasis, der reif felderig aufreisst und eine schüsselartige Restschale hinterlässt.','experte','Nur jung essbar, solange das Innere durchgehend rein weiss und fest ist; bei gelblich-oliver Sporenreife ungeniessbar. PFLICHT: jeden kugel-/beutelförmigen Fund längs aufschneiden - junge tödliche Knollenblätterpilze (Amanita) können kugelig wirken, zeigen im Schnitt jedoch Hut-/Lamellenanlagen, der Stäubling ist innen homogen weiss. Wegen dieses Amanita-Ei-Risikos Schnittkontrolle zwingend - kein Anfängerpilz.','Recherche geprüft via WebSearch (123pilzsuche, pilzbestimmer, naturemobile, Wikipedia): Offenland-Saprobiont Magerrasen/subalpine Matten, jung weissfleischig essbar, Pflicht-Längsschnitt wegen Amanita-Ei bestätigt.','f'),
('cantharellus_pallens','Lange Saison von Juni bis September (in milden Jahren bis Oktober); erscheint schubweise einige Tage bis 2 Wochen nach durchdringendem Landregen bei gleichmässiger Bodenfeuchte und 13–18 °C. Reagiert auf Feuchtigkeit etwas träger als Sommerpilze, dafür über Wochen ergiebig an denselben Stellen.','Bevorzugt kalkhaltige bis neutrale, humose, gleichmässig frische Waldböden; mag Moos- und Laubstreuauflagen, keine Trockenheit.','Mykorrhiza-Partner v. a. mit Rotbuche (Fagus) und anderen Laubbäumen; in Buchen- und Buchenmischwäldern, gern in Moospolstern und an leicht beschatteten Hängen. Zeigerstandort: krautarme Buchenhallenwälder auf Kalk.','mittel','Sehr guter Speisepilz, wächst meist gesellig in Trupps. Erkennung: blass cremeweiss bereifter Hut (typische weissliche Reifschicht, beim Reiben gilbend), herablaufende, dicke gegabelte Leisten (KEINE echten Lamellen), voller Stiel, angenehm fruchtiger Aprikosengeruch. Hauptverwechsler ist der giftige Falsche Pfifferling (echte, dünne, dicht stehende Lamellen, orangefarben) sowie der Ölbaumtrichterling – immer auf Leisten statt Lamellen achten.','123pilze, SwissFungi, Pilzführer Schweiz','f'),
('cantharellus_tubaeformis','Spätherbst-Spezialist: Hauptzeit Ende August/September bis in den Winter (November–Dezember, in milden Lagen bis Februar). Frosttolerant. Fruchtet nach den Herbstregen und hält die feuchte, kühle Spätsaison über lange durch.',NULL,'In moosigen Nadel- und Mischwäldern, v.a. unter Fichte/Tanne; gerne in dicken Moospolstern, an feuchten Senken, Gräben, morschem Holz und entlang von Bachläufen. Wächst sehr gesellig, oft in dichten Teppichen, Reihen und Ringen.','anfaenger',NULL,'Faktencheck bestätigt (WebSearch: AWL.ch, Wikipedia, 123pilzsuche) — Spätherbst/Winter bis Februar + moosige Nadelwälder korrekt, unverändert übernommen.','t'),
('cerioporus_squamosus','Frühlings- bis Frühsommerpilz, Hauptzeit April-Juli (vereinzelt bis September). Einer der ersten auffälligen Frühjahrspilze; schiebt nach den ersten milden, feuchten Frühlingswochen rasch an Laubbäumen, oft schon kurz nach ergiebigem Frühjahrsregen.','Kein Bodenpilz - wächst direkt am Holz; bevorzugt kalkreichere, frische bis feuchte Auen- und Laubwaldstandorte sowie Parkbäume.','Schwächeparasit und Saprobiont an lebenden und toten Laubbäumen, vor allem an Ahorn, Ulme, Buche, Walnuss und Esche; in Auen- und Laubwäldern, Parks und an Strassenbäumen. Konsolen einzeln oder dachziegelig übereinander, seitlich oder kurz seitlich gestielt mit schwärzlicher Stielbasis.','anfaenger','Markanter, kaum zu verwechselnder Konsolenpilz: grosser, fächerförmiger Hut mit konzentrischen dunkelbraunen Schuppen auf hellem Grund, weisse Poren statt Lamellen, schwarze Stielbasis und auffällig mehlig-gurkiger Geruch. Nur jung essbar, solange das Fleisch weich ist - im Alter korkig-zäh und ungeniessbar. Keine giftigen Doppelgänger; allenfalls mit dem ebenfalls harmlosen Sklerotienporling verwechselbar.','Recherche geprüft via WebSearch (Wikipedia, 123pilzsuche, pilzkurse.com CH, fungiversum): Porling an Laubholz (Ahorn/Ulme/Buche), Frühjahr April-Juli, jung essbar, mehlig-gurkiger Geruch, keine giftigen Verwechsler bestätigt.','f'),
('champignon-de-paris','Als Wildform (Kulturflüchtling) Frühjahr bis Spätherbst, April–November, gehäuft nach sommerlichen/herbstlichen Regenfällen. Wild eher unregelmässig und nicht häufig; in Kultur ganzjährig auf Substrat. Wildvorkommen fruchten einige Tage nach warmem Regen.',NULL,'Kein Mykorrhiza-Partner. Wild an/auf Kompost- und Misthaufen, in Gärten, an gedüngten Wiesen- und Waldrändern, in Gewächshäusern und Parks. Häufiger sind in der Schweiz die nahe verwandten Wiesen-Champignons auf Weiden und Wiesen.','mittel',NULL,'Faktencheck plausibel — Saprobiont (kein Mykorrhiza) + Kompost/Garten-Habitat + Frühjahr–Spätherbst-Saison mykologisch konsistent, unverändert übernommen.','t'),
('chlorophyllum_rhacodes','Hauptzeit Spätsommer bis Spätherbst, Juli–November mit Schwerpunkt September–Oktober; erscheint in Hexenringen oder Gruppen rund 1–2 Wochen nach Regen bei 10–18 °C, oft bis zum ersten Frost. Profitiert von nährstoffreichen, gestörten Standorten und kommt auch in trockeneren Phasen noch.','Wächst auf nährstoffreichen, humosen bis stickstoffreichen Böden; gerne auf Kompost, Mulch, Nadelstreu und gestörtem Boden, mässig frisch.','Saprobiont (Folgezersetzer, kein Mykorrhizapilz) auf Streu und nährstoffreichem Boden; in Nadel-/Mischwäldern, Parks, Gärten und an Komposthaufen. Zeigerstandort: ruderale, gedüngte Stellen, Wegränder, Gartenränder.','mittel','Guter Speisepilz (nur Hüte, gut durchgaren), wächst oft in auffälligen Gruppen. Merkmale: grobschuppiger Hut, KEIN genatterter Stiel (glatt, einfacher verschiebbarer Ring), und – entscheidend – das weisse Fleisch verfärbt sich beim Anschneiden/Reiben deutlich safran-orangerot bis bräunlich. Achtung: rohe sowie ähnliche Arten (Chlorophyllum brunneum/venenatum) können Magen-Darm-Beschwerden auslösen; nicht mit dem giftigen, in Gärten wachsenden Grünsporigen Riesenschirmling (Chlorophyllum molybdites, grünlicher Sporenstaub) verwechseln. Vom essbaren Parasol durch fehlende Stielnatterung trennen.','123pilze, DGfM, SwissFungi','f'),
('chroogomphus_rutilus','Spätsaison Juli–Oktober mit Schwerpunkt im Herbst (September–Oktober); erscheint einzeln bis gesellig rund 1–2 Wochen nach Regen bei kühleren 10–16 °C, häufig zusammen mit Schmierröhrlingen (Suillus) unter Kiefern und oft bis in den Spätherbst.','Bevorzugt saure, nährstoffarme, sandige und gut drainierte Böden; trockene bis mässig frische Kiefernstandorte.','An Kiefer (zweinadelige Pinus) gebunden, biotroph bzw. mykoparasitisch mit Schmierröhrlingen (Suillus) verbunden; in Kiefern- und sauren Nadelwäldern, oft direkt neben Butterpilzen. Zeigerstandort: moosige Kiefernforste auf Sand, wo auch Suillus wächst.','mittel','Bedingt essbar und kulinarisch wenig ergiebig (färbt Gerichte violett), aber leicht zu bestimmen und verwechslungsarm. Merkmale: kupfer- bis weinrotbrauner, schmieriger Hut, weit herablaufende, dicke, olivlich-braune bis weinrote Lamellen, spitz zulaufender Stiel ohne echten Ring (nur faserige Velumzone); Fleisch lachs-/safranrosa, beim Garen dunkelnd. Hauptmerkmal Standort unter Kiefer neben Suillus. Nicht mit dem ähnlichen Filzigen Gelbfuss verwechseln, dieser ist aber ebenfalls ungefährlich.','123pilze, SwissFungi, Pilzführer Schweiz','f'),
('clavariadelphus_truncatus','Spätsommer bis Herbst, Hauptzeit Aug–Okt (in Bergnadelwäldern oft erst ab September). Fruchtet schubweise rund 1–2 Wochen nach ergiebigem Regen bei noch milden Bodentemperaturen; mag feucht-warme Phasen nach den ersten Spätsommer-Niederschlägen. In höheren Lagen entsprechend später.','Strikt kalk- bis basenliebend (kalkhaltige, gut durchlässige Waldböden); meidet saure Standorte. Bevorzugt eher magere, moosige Nadelstreu auf Kalk.','Bergnadelwald auf Kalk, terrestrisch in der Nadelstreu unter Fichte und Tanne (vermutlich mykorrhizal/saprob assoziiert). Zeigerumfeld: kalkliebende Bergmischwälder, oft zusammen mit Moos- und Kalkzeigern; eher submontan bis montan.','mittel','Eindeutige keulen-/kreiselförmige Fruchtkörper mit auffällig flach abgestutztem, oft eingedelltem Scheitel und runzeliger ocker- bis orangegelber Oberfläche, Fleisch mild und leicht süsslich (KOH färbt blutrot). Hauptverwechsler ist die häufigere Herkuleskeule (Clavariadelphus pistillaris) mit spitz-gerundetem statt abgestutztem Scheitel und bitterem Fleisch – essbar, aber bitter, daher Geschmacksprobe (ausspucken) hilft. Keine tödlichen Doppelgänger, jedoch in der Schweiz vergleichsweise selten (in DE Rote Liste) – nur einzeln und massvoll entnehmen.','123pilze; SwissFungi (Datenbank Schweiz); DGfM; gängige Pilzführer (Laux, Gerhardt)','f'),
('clavulina_cinerea','Hochsommer bis Spätherbst, Hauptzeit Aug–Nov, schubweise ca. 1–2 Wochen nach ergiebigem Regen bei milden 10–18 °C. Profitiert von feuchten Herbstwochen und hält bis zu den ersten leichten Frösten durch.','Anspruchslos bezüglich pH, auf humosen Wald- und Wegrandböden; sowohl auf basenreichen wie mässig sauren Substraten. Mag feuchte, beschattete Bodenstellen.','Terrestrisch in Laub-, Nadel- und Mischwald sowie an Wegrändern, gesellig in Gruppen/Reihen. Gilt als Mykorrhiza-Bildner mit diversen Bäumen; Zeigerumfeld: moosige, humose Waldböden, oft an Pfaden und Böschungen.','mittel','Graue bis bleigraue, mehrfach unregelmässig verzweigte Koralle mit stumpfen, etwas abgeflachten Astspitzen; Fleisch zäh-elastisch. Nur bedingt essbar (jung und durchgegart; ältere/rohe Stücke können leicht abführend wirken) – nur junge, feste Exemplare sammeln. Verwechslung v. a. mit grauen Formen der weissen Korallen (Clavulina coralloides/rugosa) sowie mit Ramaria-Arten, von denen einige abführend giftig sind; Clavulina lässt sich makroskopisch von Ramaria abgrenzen (Astspitzen, Konsistenz). Im Zweifel Finger weg.','123pilze; SwissFungi (Datenbank Schweiz); DGfM; gängige Pilzführer (Laux, Gerhardt)','f'),
('clavulina_coralloides','Sommer bis Spätherbst, Hauptzeit Jul–Nov, schubweise einige Tage bis 2 Wochen nach Regen bei feucht-milder Witterung. Einer der früher erscheinenden Korallenpilze, hält bei mildem Herbst lange durch.','Auf humosen, eher frischen bis feuchten Waldböden; weitgehend bodenvag (kalkliebend bis mässig sauer), auch auf nackter Erde an Wegrändern.','Terrestrisch in Laub-, Nadel- und Mischwald sowie an Wegböschungen, einzeln bis gesellig. Mykorrhiza-Partner verschiedener Bäume; Zeigerumfeld: moosige, offene Bodenstellen und Pfadränder im Wald.','mittel','Weisse bis cremeweisse, dicht und fein verzweigte Koralle mit charakteristisch zugespitzten, kammartig gezähnten Astspitzen; Fleisch zäh. Nur bedingt essbar – jung und gut durchgegart, ältere Stücke geschmacklich/verträglich grenzwertig. Achtung: häufig durch den Pilzparasiten Helminthosphaeria grau überzogen, dann leicht mit der Grauen Koralle verwechselbar. Hauptrisiko sind ähnliche Ramaria-Arten (z. T. abführend) – nur typisch weisse, kammspitzige, junge Exemplare nehmen und im Zweifel verwerfen.','123pilze; SwissFungi (Datenbank Schweiz); DGfM; gängige Pilzführer (Laux, Gerhardt)','f'),
('clavulina_rugosa','Hochsommer bis Spätherbst, Hauptzeit Aug–Nov, schubweise ca. 1–2 Wochen nach ergiebigem Regen bei milden Temperaturen. Hält bei feuchtem Herbst bis zu den ersten Frösten durch.','Auf humosen Wald- und Wegrandböden, bodenvag (kalkhaltig bis mässig sauer); bevorzugt frische, leicht beschattete Stellen.','Terrestrisch in Laub-, Nadel- und Mischwald sowie an Wegrändern und Böschungen, einzeln bis büschelig. Mykorrhiza-Bildner mit verschiedenen Bäumen; Zeigerumfeld: moosige Pfadränder und offene Bodenstellen im Wald.','mittel','Weissliche bis cremefarbene, meist nur wenig (gabelig) verzweigte, runzelig-längsfaltige Keule – derber und gröber als die fein-kammspitzige Kammkoralle. Fleisch zäh, nur bedingt essbar (jung, durchgegart). Verwechslung mit anderen weissen/grauen Clavulina-Arten und mit weisslichen Clavaria/Ramaria; einige Ramaria wirken abführend. Nur junge, typisch runzelige Exemplare sammeln, ältere und parasitär vergraute Stücke meiden – im Zweifel stehen lassen.','123pilze; SwissFungi (Datenbank Schweiz); DGfM; gängige Pilzführer (Laux, Gerhardt)','f'),
('clitocybe_nebularis','Spätherbstart: September bis November/Dezember, oft als einer der letzten reichlichen Pilze der Saison, bis nahe an die ersten Fröste. Fruchtet nach den Herbstregen bei kühler, feuchter Witterung.',NULL,'In Laub- und Nadelwäldern sowie an Waldrändern, in der Falllaub-/Nadelstreu. Kein Mykorrhiza-Partner — Streuzersetzer. Wächst sehr gesellig, gerne in auffälligen, oft grossen Hexenringen und langen Reihen.','anfaenger',NULL,'Faktencheck bestätigt (WebSearch: Pilzfinder, Wikipedia, Pilzmuseum) — Spätherbst-Saison + Streuzersetzer (kein Mykorrhiza) + Hexenringe in Laub-/Nadelwald korrekt, unverändert übernommen.','t'),
('clitocybe_odora','Spätsommer bis Spätherbst, Hauptzeit Sept-Okt (Aug-Nov). Erscheint gesellig in der Streu rund 1-2 Wochen nach ergiebigem Herbstregen bei milden 8-15 °C; schiebt schubweise nach Niederschlagsperioden.','Frische, humose Wald- und Streuböden; sowohl auf sauren als auch auf kalkhaltigen Standorten. Bevorzugt feuchte, schattige Lagen, meidet dauernd nasse Stellen.','Saprob (kein Mykorrhiza-Partner) in der Laub- und Nadelstreu von Laub-, Nadel- und Mischwäldern, gern entlang von Wurzeln und an Wegrändern. Zeigerumfeld: Buche und Fichte, krautreiche Waldsäume.','mittel','Eindeutigstes Merkmal ist der starke, süssliche Anis-/Marzipangeruch zusammen mit dem blassgrün-blaugrünen Hut - diese Kombination hat kein giftiger Pilz. Trotzdem mit Vorsicht: junge oder verblasste Exemplare können weisslichen, giftigen Trichterlingen ähneln, daher immer den Anisgeruch und die am Stiel herablaufenden Lamellen prüfen. Wird nur als sparsamer Würzpilz verwendet, nicht als Hauptspeisepilz.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert','f'),
('clitopilus_prunulus','Sommer bis Herbst, Hauptzeit Aug-Sept (Jul-Nov). Fruchtkörper erscheinen einzeln bis gesellig einige Tage bis ~1-2 Wochen nach durchdringendem Regen bei warmen 12-18 °C.','Nährstoffreiche, eher kalkhaltige bis neutrale, gut durchfeuchtete Wald- und Parkböden; meidet stark saure, magere Standorte.','Saprob auf nackten Erdstellen, an Waldwegen, Böschungen und Waldrändern in Laub-, Nadel- und Mischwald sowie Parkanlagen; oft an lichten, grasigen Stellen. Häufig in der Nähe von Steinpilz-Standorten ("Steinpilz-Wegweiser").','experte','ACHTUNG hohe Verwechslungsgefahr: der weisse Hut mit anfangs weissen, im Alter rosa werdenden, herablaufenden Lamellen ähnelt tödlich giftigen weissen Trichterlingen (Clitocybe rivulosa/dealbata) und Risspilzen. Sicheres Merkmal ist der starke, frische Mehl-/Gurkengeruch und das rosa Sporenpulver (Sporenabwurf machen!). Nur für Erfahrene; im Zweifel stehen lassen.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert','f'),
('coprinellus_micaceus','Nahezu ganzjährig (Frühjahr bis Spätherbst, Schwerpunkt Apr-Nov), bei mildem Wetter auch im Winter. Erscheint büschelig schon 2-5 Tage nach Regen und vergeht rasch; am besten morgens jung sammeln, da die Hüte innerhalb eines Tages zertintlern.','Feuchte, humus- und holzreiche Böden; anspruchslos bezüglich pH. Braucht morsches Holz oder vergrabene Holzreste im Untergrund.','Saprob (Holzzersetzer) in dichten Büscheln an und über morschem Laubholz, an Stümpfen, Wurzeln und auf Rasen über vergrabenem Holz in Laub-/Mischwald, Gärten und Parks. Kein Mykorrhiza-Partner.','mittel','Gut kenntlich am büscheligen Wuchs, dem eiförmig-glockigen, fein gerieften Hut mit den glimmerartigen, glitzernden Velumkörnchen (am besten an jungen, trockenen Exemplaren sichtbar) und am späteren Zertintlern der Lamellen. Nur ganz junge, noch geschlossene Hüte sammeln und rasch verarbeiten; vorsichtshalber ohne Alkohol geniessen.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert','f'),
('coprinopsis_atramentaria','Frühjahr bis Spätherbst, Hauptzeit Mai-Okt (Apr-Nov). Schiebt büschelig wenige Tage nach kräftigem Regen bei mildem Wetter; Fruchtkörper zerfliessen schnell, daher jung und zeitnah ernten.','Nährstoff- und humusreiche, feuchte Böden in Siedlungsnähe; anspruchslos, oft auf gestörten, gedüngten Standorten. Holzreste im Untergrund begünstigen das Wachstum.','Saprob in dichten Büscheln über vergrabenem Holz, an Stümpfen, Wegrändern, in Gärten, Parks und Laub-/Mischwald auf humusreichem Boden. Kein Mykorrhiza-Partner.','mittel','Kenntlich am büscheligen Wuchs, dem graubraunen, oben oft schwach schuppigen Faltenhut und dem typischen Zertintlern von unten her. WICHTIG: enthält Coprin - in Kombination mit Alkohol (auch noch 1-2 Tage davor/danach) kommt es zum Antabus-Effekt (Übelkeit, Herzrasen, Rötung). Nur jung, gut durchgegart und strikt alkoholfrei verzehren.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert','f'),
('cortinarius_praestans','Spätsommer bis Herbst, Hauptzeit Sep–Okt (ab Aug möglich), schubweise rund 1–2 Wochen nach ergiebigem Spätsommer-/Herbstregen bei noch milder, wärmeliebender Witterung. Reagiert deutlich auf die ersten grossen Herbstniederschläge.','Strikt kalk-/basenliebend: warme, kalkhaltige, meist naturnahe Laubwaldböden; meidet bodensaure Standorte.','Mykorrhiza-Partner v. a. der Buche, daneben Eiche und Hainbuche; thermophiler Kalk-Laubwald (Buchen-/Eichenwald). Zeigerumfeld: lichte, warme Kalkbuchenwälder mit Kalkzeigerpflanzen im Unterwuchs.','experte','Grosser, fleischiger Schleimkopf mit anfangs eingerolltem, braun-violett überlaufenem Hut mit weisslichen Velumfasern/-flecken und kräftigem, oft blau-violett angehauchtem Stiel mit Cortina (Schleier); junge Lamellen tonbraun. Gilt als einziger marktfähiger Schleierling – ABER die Gattung Cortinarius enthält tödlich giftige Arten (u. a. der orellaninhaltige Orange-/Spitzgebuckelte Raukopf mit Spätnieren-Versagen). Daher nur für Erfahrene: Rostbraunes Sporenpulver und alle Eulen-Merkmale müssen passen; jede Unsicherheit, kleinere/schlanke oder leuchtend orange-braune Schleierlinge strikt meiden. Im Zweifel zur Pilzkontrolle.','123pilze; SwissFungi (Datenbank Schweiz); DGfM; VAPKO/Schweizer Speisepilz-Verordnung; gängige Pilzführer (Laux, Gerhardt)','f'),
('craterellus_lutescens','Herbstpilz, Hauptzeit Sept-Okt (Aug-Nov bis zum ersten Frost). Erscheint in dichten Truppen etwa 1-2 Wochen nach anhaltendem Herbstregen bei kühlen 8-14 °C; an guten Stellen jahrelang am selben Fleck.','Kalkhaltige bis schwach saure, feuchte, moosige und torfige Nadelwaldböden; bevorzugt dauerfeuchte, schattige Lagen.','Mykorrhiza-Partner v.a. Fichte (auch Kiefer/Nadelbäume) in feuchten, moosigen Nadel- und Mischwäldern; oft in Moospolstern, an Bachsäumen und in Mulden. Zeigerumfeld: dichte Moosdecken unter Fichten auf Kalk.','mittel','In Truppen wachsend, daher beim Fund meist reichlich. Erkennbar am trichterig-durchbohrten, graubraunen Hut, den fast glatten bis schwach geaderten Leisten und dem leuchtend gelb-orangen, hohlen Stiel sowie dem kräftig-aromatischen Geruch. Verwechslung praktisch nur mit anderen essbaren Leistlingen/Trompetenpfifferlingen (C. tubaeformis) - kein gefährlicher Doppelgänger.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert','f'),
('cuphophyllus_pratensis','Herbstpilz, Hauptzeit Sep–Nov, schubweise einige Tage bis ~2 Wochen nach ergiebigem Herbstregen bei kühl-milder, taureicher Witterung. Erscheint typischerweise erst nach den ersten kühleren, feuchten Herbsttagen und übersteht leichte Fröste.','Magere, ungedüngte, eher basenreiche bis neutrale Grünlandböden; meidet stickstoffüberdüngte Fettwiesen. Mag intakte, alte Magerrasen.','Saprobiontisch im kurzrasigen Magergrünland: ungedüngte Magerwiesen, Weiden, Parkrasen und Böschungen, gesellig in Gruppen/Hexenringen. Zeigerumfeld: artenreiche Magerwiesen mit weiteren Saftlingen (Hygrocybe), Zeiger für nährstoffarme, naturnahe Wiesen.','experte','Orange-lachsfarbener bis cremebrauner, im Alter blass aufschirmender Hut mit weit am Stiel herablaufenden, dicklich-entferntstehenden Lamellen in Hutfarbe und weissem Sporenpulver; Stiel hutfarben-blass, ohne Ring. ACHTUNG Wiesen-Falle: in genau denselben Magerwiesen wachsen kleine weisse, muscarinhaltige Trichterlinge (Clitocybe dealbata/rivulosa-Gruppe), deren herablaufende Lamellen Anfänger täuschen – Verwechslung kann schwere Vergiftungen verursachen. Nur mit sicherer Saftlings-Erfahrung sammeln: wachsartige Konsistenz, dicke entfernte Lamellen, kein mehlig-ranziger Trichterlings-Geruch; im Zweifel stehen lassen (zudem in DE/teils CH geschützt – schonen).','123pilze; SwissFungi (Datenbank Schweiz); DGfM; gängige Pilzführer (Laux, Gerhardt)','f'),
('cuphophyllus_virgineus','Hauptzeit September–November (in milden Lagen bis Dezember); erscheint einige Tage bis ~2 Wochen nach ergiebigem Herbstregen bei kühlem Wetter (ca. 6–14 °C), oft truppweise und gern nach den ersten Nachtfrösten.','Magere, ungedüngte, eher saure bis neutrale Böden; bevorzugt nährstoffarme, mässig frische bis trockene Standorte ohne Düngung.','Kein Mykorrhizapilz, sondern saprob im Grasfilz von Magerwiesen, Weiden, moosigen Rasen, Parkrasen und Friedhöfen. Zeigerstandort sind ungedüngte Saftlingswiesen (Magerrasen mit Moospolstern).','experte','Auf ungedüngten Magerwiesen nach kleinen, rein- bis glasigweissen, etwas durchscheinenden Fruchtkörpern mit schmierig-fettigem Hut, weit herablaufenden, entfernten weissen Lamellen und mildem Geschmack suchen. ACHTUNG – im selben Wiesen-Habitat wachsen tödlich giftige weisse Trichterlinge (Clitocybe rivulosa, C. dealbata) mit gedrängten, nicht weit herablaufenden Lamellen und mehligem Geruch sowie weisse Risspilze. Nur bei zweifelsfreier Bestimmung (wachsartige, weit herablaufende Lamellen, schmieriger Hut) sammeln; für Anfänger wegen der lebensgefährlichen weissen Wiesenpilze nicht geeignet.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt); Wikipedia','f'),
('cyanoboletus_pulverulentus','Sommer bis Herbst, Hauptzeit Jul-Sept (Jun-Okt). Erscheint einzeln bis gesellig rund 1-2 Wochen nach ergiebigem Regen bei warmen 15-20 °C, gern an feuchten, schattigen Stellen.','Frische bis feuchte, eher saure bis neutrale Laubwaldböden; oft an verdichteten, feuchten Stellen an Wegen und Gräben.','Mykorrhiza-Partner v.a. Buche und Eiche (auch Edelkastanie, diverse Laubbäume) in Laub- und Mischwäldern, Parks, an Wegrändern und im Gras. Zeigerumfeld: feuchte Buchen-/Eichenbestände.','mittel','Unverwechselbares Merkmal: bei der geringsten Berührung oder beim Anschnitt verfärben sich Poren, Fleisch und Stiel sofort intensiv tinten- bis schwarzblau. Hut olivbraun, Poren jung gelb. Gilt nur als bedingt essbar, da er Schwermetalle (Cadmium) anreichern kann - daher nur junge Exemplare und in Massen geniessen, nicht in belasteten Lagen sammeln.','123pilze, SwissFungi, DGfM, gängige Pilzführer - mykologisches Standardwissen, vorsichtig formuliert','f'),
('cyclocybe_aegerita','Hauptzeiten Frühling (April–Juni) und Herbst (September–November); erscheint schubweise einige Tage bis ~2 Wochen nach feucht-milder Witterung mit Temperaturen um 10–20 °C. Profitiert von milden, regenreichen Perioden und kann bei frostfreiem Wetter auch in milden Wintern büschelig nachschieben.','Standort-unabhängig vom Boden, da holzbewohnend (saprob); bevorzugt feuchte, nährstoffreiche Auen- und Parkstandorte mit reichlich Laubholz-Totholz.','Saprob (kein Mykorrhiza-Partner): büschelig an Strünken und morschem Stammholz von Pappel, seltener Weide, Holunder, Ahorn und anderen Laubbäumen. Typisch in Auwald, Parkanlagen und Flussufern.','mittel','Büschelig an Laubholz-Strünken (v. a. Pappel) suchen; Hut jung halbkugelig-braun und glatt, im Alter ockerblass und feinrissig aufreißend. Sicheres Merkmal: häutiger Ring am Stiel und tabakbrauner Sporenstaub. Vorsicht vor braunsporigen Holzbewohnern wie dem tödlichen Gifthäubling (Galerina) – bei Ringpilzen an Holz immer Sporenfarbe und Habitus genau prüfen.','123pilze, DGfM, SwissFungi; gängige Pilzführer','f'),
('disciotis_venosa','Frühjahr, Hauptzeit März–Mai (parallel zur Morchelsaison); erscheint nach mildem, feuchtem Vorfrühlingswetter etwa 1–2 Wochen nach Regen, sobald die Böden sich auf ca. 8–14 °C erwärmen, oft an denselben Stellen wie Morcheln.','Feuchte, humose, eher kalkhaltige bis neutrale Böden; bevorzugt nährstoffreiche, frische bis nasse Auen- und Uferböden.','Kein Mykorrhizapilz, sondern saprob auf humosen, feuchten Böden in Auwäldern, Laubwäldern, an Ufergehölzen, Wegrändern und in Gebüschen. Zeigerstandorte sind feuchte Auen- und Hangwälder mit Eschen, Erlen und Weiden.','experte','Flache, becher- bis tellerförmige, braune Fruchtkörper mit aussen weisslicher, kleiig-höckeriger Unterseite und im Alter gerippt-aderiger Innenseite suchen; typisch ist der deutliche Chlor-/Javel-Geruch (verschwindet beim Kochen). NUR gut durchgegart geniessbar – roh giftig. Abzugrenzen von Lorcheln/Scheibenlorcheln (Gyromitra/Discina: kein Chlorgeruch, meist an Nadelholz, giftiges Gyromitrin) und geruchlosen Becherlingen (Peziza). Wegen der giftigen Lorchel-Verwechsler und der Roh-Giftigkeit nur für erfahrene Sammler.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt); Wikipedia','f'),
('eierschwamm','Juni bis Oktober (Hauptzeit Juli–September), in guten Jahren bis Spätherbst. Fruchtet, wenn Bodenfeuchte und Wärme zusammenfallen: 1–2 Wochen nach ergiebigem Regen bei milden 15–25°C. Nach trocken-heissem Frühsommer wirkt die erste Regenperiode oft schon nach 48–72 h.','Bevorzugt nährstoffarme, eher saure Böden; gedeiht in Fichten-, Buchen- und Mischwäldern auf solchen Standorten.','Mykorrhiza mit Fichte, Buche, Eiche, Kiefer und Tanne. In Fichten-, Buchen- und Mischwäldern; oft an moosigen Stellen, Waldrändern, Böschungen und lichten Partien. Wächst gesellig in Gruppen, selten einzeln.','anfaenger','Nach ergiebigem Regen 1–2 Wochen später an moosigen, lichten Stellen und Böschungen suchen; wächst gesellig in Gruppen, deshalb beim ersten Fund die Umgebung genau absuchen.','Mykologisch plausibel bestätigt (Cantharellus cibarius): Saison Juni–Oktober mit Schwerpunkt Juli–September, Mykorrhiza mit Fichte/Buche/Eiche/Kiefer/Tanne, nährstoffarme saure Böden. Quellen: Wikipedia (Echter Pfifferling), AWL.ch, fungiversum.de. Unverändert übernommen.','t'),
('fistulina_hepatica','Spätsommer bis Herbst, Hauptzeit August–Oktober; einzelne Fruchtkörper ab feucht-warmer Witterung, etwa 1–2 Wochen nach Regen bei wärmeren Temperaturen. Wächst langsam über Wochen am selben Baum, daher kein klassisches Massen-Schubverhalten.','Bodenunabhängig (holzbewohnend, schwächeparasitisch/saprob); bevorzugt warme, thermophile Laubmischwälder auf eher trockenen, sonnenexponierten Lagen.','Schwächeparasit/Saprob an lebenden und toten Stämmen: meist an der Stammbasis oder am unteren Stamm alter Eichen, seltener an Edelkastanie. Zeigt alte, vitale Eichenbestände an.','anfaenger','An der Basis alter Eichen nach dem unverkennbaren zungen- bis leberförmigen, blutrot bis leberbraun gefärbten Konsolenpilz suchen. Frische Schnittfläche ist rot marmoriert und sondert einen rötlichen Saft ab; die Röhrenschicht lässt sich einzeln ablösen. Nur jung und essbar verwerten – durch hohen Säuregehalt eigenwillig sauer (bedingt essbar). Praktisch verwechslungsfrei.','123pilze, DGfM, SwissFungi; gängige Pilzführer','f'),
('flaemmling','August bis November, schwerpunktmässig im feuchten Herbst. Erscheint büschelig nach Regenperioden, wenn das Totholz gut durchnässt ist; mag feuchte, kühlere Witterung.','Nicht bodengebunden – Holzbewohner (Saprobiont). Substrat ist durchnässtes, morsches Laubholz; gedeiht besonders in feuchten Senken und Bach-/Auennähe.','An morschem, totem Laubholz, bevorzugt Rotbuche und Eiche (selten Nadelholz). Dicht gedrängt in vielhütigen Büscheln an Stubben, Stümpfen und am Boden liegenden Stämmen, oft in Bach-/Auennähe und feuchten Senken.','mittel','An Laubholz-Stümpfen und liegenden Stämmen in feuchten Senken suchen; die auffälligen vielhütigen Büschel sind gut erkennbar, treten aber nur nach durchnässtem Totholz auf.','Mykologisch plausibel bestätigt – die Angaben (büschelig, Laubholz Rotbuche/Eiche, Aug–Nov) beschreiben den Beringten Flämmling (Gymnopilus junonius), nicht den Geflecktblättrigen (G. penetrans, der auf Nadelholz wächst). Für G. junonius korrekt: dichte Büschel an totem Laubholz (Buche/Eiche), Saison August–Oktober/November. Quellen: fundkorb.de, digital-nature.de, tintling.com. Unverändert übernommen.','t'),
('flammulina_velutipes','Spätherbst bis Vorfrühling (Oktober–März), echter Winterpilz; erscheint oft während oder kurz nach milderen Phasen zwischen Frostperioden. Ein Frost-Tau-Wechsel mit feuchtem, mildem Wetter um 0–10 °C löst die Schübe aus; verträgt Durchfrieren und treibt danach erneut aus.','Bodenunabhängig (saprob, holzbewohnend); typisch in feuchten Laubwäldern, an Bach- und Flussufern, in Parks und Gärten.','Saprob: büschelig an Totholz, Strünken, Stämmen und Ästen von Laubbäumen (v. a. Weide, Pappel, Esche, Ulme, Buche). Oft an absterbenden oder geschwächten lebenden Bäumen.','experte','Büschel an Laubholz im Winter suchen: orangebrauner, schmieriger Hut und vor allem der namensgebende samtig-dunkelbraune bis schwarze Stiel im unteren Teil. ACHTUNG: Der tödlich giftige Gifthäubling (Galerina marginata) wächst im selben Holz-Habitat und ähnelt jungen Exemplaren – Samtfuß hat weißen Sporenstaub und KEINEN Ring, Galerina rostbraunen Sporenstaub und einen Ring. Im Zweifel Sporenabwurf machen; nur für Geübte.','123pilze, DGfM, SwissFungi; gängige Pilzführer','f'),
('flockenstieliger_hexenpilz','Einer der frühesten Röhrlinge: ab Mai (vereinzelt April) bis Oktober/November, gelegentlich bis Dezember. Schiebt nach warmen Regenphasen im Sommer und Herbst, oft in grösseren Gruppen bei feuchter Witterung.','Saure bis schwach saure Böden bevorzugt (gelegentlich auch auf kalkhaltigem Substrat). Typisch in sauren Nadel-, Misch- und Buchenwäldern.','Mykorrhiza vor allem mit Fichte, daneben Buche, Eiche, Tanne und andere Nadelbäume. In sauren Nadel-, Misch- und Buchenwäldern; gern an Wegrändern und lichten Stellen mit Heidelbeere/Moos.','anfaenger','Schon ab Mai an Wegrändern und lichten Stellen mit Heidelbeere/Moos in sauren Nadel- und Mischwäldern suchen; erscheint nach warmen Regenphasen oft in grösseren Gruppen.','Mykologisch plausibel bestätigt (Neoboletus erythropus): einer der frühesten Röhrlinge (ab Mai, vereinzelt April), Mykorrhiza mit Fichte/Buche/Eiche/Tanne, saure bis schwach saure Böden in Nadel-/Misch-/Buchenwäldern. Quellen: Wikipedia, fungiversum.de, AWL.ch. Unverändert übernommen.','t'),
('flockenstieliger-hexen-roehrling','Einer der frühesten Röhrlinge: ab Mai (vereinzelt April) bis Oktober/November, gelegentlich bis Dezember. Schiebt nach warmen Regenphasen im Sommer und Herbst, oft in grösseren Gruppen bei feuchter Witterung.','Saure bis schwach saure Böden bevorzugt (gelegentlich auch auf kalkhaltigem Substrat). Typisch in sauren Nadel-, Misch- und Buchenwäldern.','Mykorrhiza vor allem mit Fichte, daneben Buche, Eiche, Tanne und andere Nadelbäume. In sauren Nadel-, Misch- und Buchenwäldern; gern an Wegrändern und lichten Stellen mit Heidelbeere/Moos.','anfaenger','Schon ab Mai an Wegrändern und lichten Stellen mit Heidelbeere/Moos in sauren Nadel- und Mischwäldern suchen; erscheint nach warmen Regenphasen oft in grösseren Gruppen.','Mykologisch plausibel bestätigt (Neoboletus erythropus, identisch zu Slug flockenstieliger_hexenpilz): früher Röhrling ab Mai, Mykorrhiza mit Fichte/Buche/Eiche/Tanne, saure Böden. Quellen: Wikipedia, fungiversum.de, AWL.ch. Unverändert übernommen.','t'),
('gomphidius_glutinosus','Sommer bis Herbst, Hauptzeit Juli–Oktober; erscheint einige Tage bis ~2 Wochen nach ergiebigem Regen bei kühl-feuchter Witterung um 10–16 °C, häufig parallel zur Fichten-Steinpilz-Saison in montanen Lagen.','Saure bis neutrale, eher frische bis feuchte Nadelwaldböden; oft auf Rohhumus über sauren Silikat- oder Moränenböden in Berglagen.','Mykorrhiza mit Fichte (Picea); typisch in montanen Fichten- und Bergmischwäldern, oft moosreich. Folgt der Fichte als verlässlichem Zeigerbaum.','mittel','Unter Fichten im Moos suchen; stark schleimig-glänzender grau- bis purpurbrauner Hut, weit am Stiel herablaufende, jung weißliche, im Alter grau-schwärzliche Lamellen und eine leuchtend gelbe Stielbasis. Schwarzer Sporenstaub. Vor dem Verzehr die schleimige Huthaut abziehen (bedingt essbar). Recht charakteristisch, dennoch Schleimpilz-typische Merkmale sorgfältig abgleichen.','123pilze, DGfM, SwissFungi; gängige Pilzführer','f'),
('grifola_frondosa','Spätsommer bis Herbst, Hauptzeit August–Oktober (bis November); erscheint nach längeren feucht-warmen Perioden, oft 1–2 Wochen nach kräftigem Regen bei 15–22 °C. Wächst über mehrere Tage zu einem großen Fruchtkörper heran und kann jahrelang am selben Baum wiederkehren.','Bodenunabhängig (holzbewohnend, schwächeparasitisch/saprob am Wurzel- und Stammfuß); bevorzugt warme, eher basenreiche Laubwaldstandorte.','Schwächeparasit/Saprob an der Stammbasis und im Wurzelbereich alter Eichen, seltener Buche, Kastanie oder Linde. Zeigt alte, anbrüchige Eichen an; oft jahrelang am gleichen Baumstumpf.','mittel','Am Fuß alter Eichen nach der großen, halbkugeligen Rosette aus vielen grau-braunen, fächerförmigen Hütchen über verzweigtem weißem Strunk suchen (Poren statt Lamellen). Nur jung und zart ernten. Verwechselbar mit Riesenporling (Meripilus giganteus, schwärzt auf Druck) und Eichhase (Polyporus umbellatus) – Wuchsbild, Porenschicht und Verfärbung prüfen.','123pilze, DGfM, SwissFungi; gängige Pilzführer','f'),
('gymnopus_dryophilus','Lange Saison Mai–November mit Hauptzeit Spätsommer/Herbst; erscheint schubweise einige Tage nach Regen bei milden Temperaturen (ca. 10–18 °C), häufig truppweise im Falllaub.','Saure, humose Wald- und Streuböden; bevorzugt mässig frische, nährstoffärmere Standorte mit dicker Laub-/Nadelstreu.','Kein Mykorrhizapilz, sondern saprob auf Falllaub, Nadelstreu und morschem Holz in Laub-, Nadel- und Mischwäldern, besonders unter Eichen und Buchen. Zeigerstandort sind streureiche, bodensaure Wälder.','experte','Kleiner Rübling mit je nach Feuchte gelb- bis kastanienbraunem, hygrophanem Hut (trocken creme/weisslich), zähem, glattem Stiel und blassen, gedrängten Lamellen; nur jung, gut durchgegart und in kleinen Mengen geniessbar (bei empfindlichen Personen Magen-Darm-Reizung, daher nur bedingt essbar). ACHTUNG – kleiner brauner Pilz mit zahlreichen, oft nur mikroskopisch trennbaren Rübling-Doppelgängern; im selben Streu-/Holz-Habitat wächst der tödliche Gift-Häubling (Galerina marginata, brauner Sporenstaub, häutiger Ring). Wegen der Verwechslungsgefahr mit kleinen braunen Giftpilzen nur für erfahrene Sammler.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt); Wikipedia','f'),
('gyroporus_cyanescens','Hauptzeit Juli–Oktober (vereinzelt ab Juni); erscheint einige Tage bis ~2 Wochen nach durchdringendem Sommer-/Herbstregen bei warmen Bodentemperaturen (ca. 14–20 °C), meist einzeln oder in kleinen Gruppen.','Saure, sandige bis kiesige, magere Böden; meidet kalkreiche Standorte und bevorzugt gut drainierte, nährstoffarme Sauerböden.','Mykorrhizapilz an Laub- und Nadelbäumen, vor allem Birke, Kiefer und Eiche, in lichten Wäldern, an Wegrändern und Sandgruben auf Sauerboden. Zeigerstandort sind sandige, saure Birken-/Kiefernwälder und Heidekiefernwälder.','mittel','In sandigen, sauren Birken-/Kiefernwäldern nach blass strohgelbem bis ockerlichem, fein filzigem Röhrling mit brüchigem, kammerig-hohlem Stiel suchen. Entscheidendes Bestimmungsmerkmal: das weisslich-gelbe Fleisch und die Poren laufen beim Anschneiden bzw. Druck sofort intensiv kornblumenblau an. Verwechslungsarm, da kein gefährlicher Röhrling so rasch und intensiv blaut und gleichzeitig den brüchigen Hohlstiel zeigt; im Zweifel die schlagartige Blauverfärbung und den hohlen Stiel prüfen.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt)','f'),
('hallimasch','Hauptsächlich Herbst: Juli/August bis November, je nach Witterung bis Dezember. Schiebt schubweise nach den ersten kühl-feuchten Herbstregen, oft massenhaft an einem Tag.','Nicht bodengebunden – Holzbewohner (Parasit/Saprobiont). Besiedelt Stämme, Stubben und (auch vergrabene) Wurzeln lebender wie toter Bäume; erscheint scheinbar aus dem Boden über Rhizomorphe.','Büschelig an Stämmen, Stubben, Wurzelstöcken und am Wurzelboden lebender wie toter Bäume; in Mitteleuropa vor allem an Laubholz. Auch in Parks, Grünanlagen und Gärten. Über Rhizomorphe oft scheinbar aus dem Boden, tatsächlich an vergrabenen Wurzeln.','anfaenger','Nach den ersten kühl-feuchten Herbstregen schubweise an Stämmen, Stubben und Wurzelstöcken suchen – auch in Parks und Gärten; erscheint oft massenhaft an einem Tag in dichten Büscheln.','Mykologisch plausibel (Armillaria spec.): Herbstpilz, büschelig an Holz/Stubben/Wurzeln lebender und toter Bäume, über Rhizomorphe scheinbar bodenständig, auch in Parks/Gärten. Allgemein gesichertes mykologisches Wissen. Unverändert übernommen.','t'),
('hemileccinum_impolitum','Sommer bis Frühherbst, Hauptzeit Juni–September (bis Oktober); wärmeliebend, erscheint einige Tage bis ~2 Wochen nach Regen in warmen Perioden um 18–25 °C. Profitiert stark von schwül-warmer Gewitterwitterung an thermophilen Standorten.','Warme, basen- bis kalkreiche, eher trockene Laubwaldböden; bevorzugt kalkige, sonnenexponierte Lagen.','Mykorrhiza v. a. mit Eiche (Quercus), auch Hainbuche und Rotbuche; typisch in lichten, warmen Eichen- und Laubmischwäldern sowie Parkanlagen auf Kalk. Eiche und warmer Kalkstandort als Zeiger.','mittel','Unter Eichen an warmen Kalkstandorten nach dem hellen, blass lederbraunen Röhrling mit gelben Poren und gelblichem, kaum oder nur schwach blauendem Fleisch suchen. Charakteristisch ist der jodartig-medizinische Geruch in der Stielbasis. Wie bei allen Röhrlingen Fleischverfärbung, Poren- und Stielmerkmale prüfen und blauende oder rotporige Arten sicher ausschließen.','123pilze, DGfM, SwissFungi; gängige Pilzführer','f'),
('herbsttrompete','Spätsommer bis Herbst: ab Mitte August, Schwerpunkt September–Oktober (lokal bis November). Erscheint nach ergiebigen Niederschlägen im Spätsommer/Herbst; in guten Jahren als Massenpilz.','Kalkhaltige, eher nährstoffarme Böden; gedeiht in Laub- und Mischwäldern auf solchem Untergrund, oft an feuchten, schattigen Stellen.','Mykorrhiza vor allem mit Rotbuche (Fagus sylvatica), auch Eiche. In Laub- und Mischwäldern auf kalkhaltigem Untergrund; oft an feuchten, moosigen, schattigen Stellen, gern an Hängen und in Mulden, gesellig in dichten Trupps.','mittel','Nach ergiebigem Regen an feuchten, moosigen, schattigen Stellen unter Rotbuche auf Kalkboden suchen, gern an Hängen und in Mulden; die dunkle Färbung tarnt sie im Laub – langsam und genau am Boden absuchen, dann oft in dichten Trupps.','Mykologisch plausibel bestätigt (Craterellus cornucopioides): Mykorrhiza vor allem mit Rotbuche (auch Eiche) auf Kalkboden, Hauptsaison Spätsommer–Herbst (Aug–Nov), feuchte schattige Stellen, gesellig in Trupps. Schwer zu sehen wegen dunkler Tarnfärbung → ''mittel'' plausibel. Quellen: Wikipedia (Totentrompete), AWL.ch, fundkorb.de. Unverändert übernommen.','t'),
('hericium_coralloides','Hauptzeit Sept–Okt (vereinzelt ab Aug bis Nov), ca. 1–2 Wochen nach feucht-kühler, regnerischer Witterung bei 8–15 °C. Fruchtet meist nur einmal pro Jahr am selben Totholzstamm, das Myzel kann aber über mehrere Jahre an derselben Stelle wiederkommen.','Standortunabhängig vom Mineralboden, da holzbewohnend; bevorzugt feuchte, schattige, luftfeuchte Lagen mit langsam vermoderndem Laubholz. Häufiger in luftfeuchten Buchen-Hangwäldern und entlang von Bachtälern.','Saprobiont (Holzzersetzer, kein Mykorrhiza-Partner) an liegendem und stehendem Totholz von Laubbäumen, vor allem Rotbuche (Fagus), seltener Esche, Ahorn, Eiche; sehr selten an Tanne. Zeigerstandort: alte, naturnahe Buchen-Mischwälder mit hohem Totholzanteil.','anfaenger','Charakteristisch ist der korallenartig verzweigte weisse Fruchtkörper mit kurzen (3–10 mm) Stacheln, die ausschliesslich an den herabhängenden Astenden sitzen. Verwechslung praktisch ausgeschlossen, es gibt keine giftigen Doppelgänger. An morschen liegenden Buchenstämmen und Ästen suchen, oft auf der Unterseite oder an Bruchstellen. Junge, rein weisse Exemplare ernten; vergilbte oder bräunliche sind überständig und bitter. Achtung: Stachelbärte sind in der Schweiz geschützt bzw. selten – nur massvoll und nur sicher bestimmt sammeln.','123pilze.de; SwissFungi (WSL); DGfM-Artbeschreibung; Breitenbach/Kränzlin Pilze der Schweiz','f'),
('hericium_erinaceus','Hauptzeit Sept–Okt (bis in milde Novemberwochen), erscheint ca. 1–2 Wochen nach ergiebigen Niederschlägen bei kühlen 10–18 °C, meist im Spätsommer/Herbst. Bildet oft nur einen einzelnen grossen Fruchtkörper pro Baum, der über mehrere Wochen weiterwächst; kehrt jahrelang am selben Stamm wieder.','Holzbewohnend, daher mineralbodenunabhängig; gedeiht in luftfeuchten, warmen Laubwald-Lagen. Bevorzugt klimatisch begünstigte, eher tiefere Lagen mit alten, starken Laubbäumen.','Schwächeparasit und Saprobiont an lebenden, verletzten sowie toten alten Laubbäumen (Wundparasit), vor allem an Buche und alter Eiche, seltener Walnuss/Ahorn. Wächst typischerweise aus Stammwunden, Astabbrüchen oder Höhlungen in mehreren Metern Höhe. Zeigerstandort: alte Hutewälder, Parkbäume und naturnahe Laub-Altholzbestände.','anfaenger','Unverwechselbar: kompakter, kissenförmiger weisser Fruchtkörper mit langen (1–5 cm), bartartig herabhängenden Stacheln (Löwenmähne). Keine giftigen Doppelgänger. An Stammwunden und Astlöchern alter Buchen/Eichen Ausschau halten, oft in Augenhöhe bis mehrere Meter hoch. Nur frische, reinweisse Exemplare ernten; gelblich-bräunliche sind alt und zäh-bitter. In der Schweiz selten und schützenswert – nur einzeln und sicher bestimmt entnehmen.','123pilze.de; SwissFungi (WSL); DGfM-Artbeschreibung; Laux Der grosse Kosmos Pilzführer','f'),
('hortiboletus_rubellus','Hauptzeit Juli–Sept (vereinzelt Juni und bis Okt), erscheint ca. 1 Woche nach warmem Sommerregen bei 16–22 °C. Wärmeliebend, schubweises Erscheinen nach Gewitterregen; gehört zu den ersten Sommer-Röhrlingen.','Mässig nährstoffreiche, oft eher trockenwarme, neutrale bis schwach saure Böden; verträgt verdichtete und gestörte Böden. Häufig an grasigen, sonnigen Standorten.','Mykorrhiza-Partner vor allem von Eiche (Quercus) und Linde (Tilia), auch Hainbuche und Rotbuche. Typisch an warmen, lichten Stellen: Waldränder, Parkrasen, Friedhöfe, Stadtparks, Alleen und Wegränder. Zeigerstandort: einzelstehende Eichen/Linden auf kurzem Rasen.','mittel','Kleiner Filzröhrling mit oliv-rotbraunem, oft feinrissigem Hut, leuchtend roter, fein gepunkteter Stieloberfläche und gelben Poren, die bei Druck blauen. Sicherstes Merkmal: im Stielbasis-Fleisch winzige karottenrote bis orangerote Pünktchen (nur längs aufschneiden!). Nur bedingt essbar (jung, gut durchgegart, kleine Mengen) und geschmacklich schwach – kein Sammelpilz für die Küche im grossen Stil. Schwammig-alte und madige Exemplare meiden. Verwechselbar mit anderen Filzröhrlingen, alle gelten als ungiftig, aber Bestimmung der Rotfuss-Gruppe erfordert Erfahrung.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt BLV Handbuch Pilze','f'),
('hydnum_albidum','Hauptzeit August–November; erscheint einige Tage bis ~2 Wochen nach ergiebigem Spätsommer-/Herbstregen bei mildem Wetter (ca. 8–16 °C), oft gesellig in Hexenreihen oder Gruppen.','Kalkhaltige, basenreiche, humose Böden; bevorzugt frische, mässig nährstoffreiche Standorte mit Moos- und Laubauflage.','Mykorrhizapilz an Laub- und Nadelbäumen (Buche, Eiche, Hainbuche, Fichte) in Laub- und Mischwäldern auf Kalk. Zeigerstandort sind moosige, kalkhaltige Buchen-/Mischwälder.','anfaenger','Der weissliche Semmelstoppelpilz trägt auf der Hutunterseite statt Lamellen oder Röhren weiche, herablaufende Stacheln (Stoppeln) – dieses Merkmal schliesst eine Verwechslung mit giftigen Blätter- oder Röhrenpilzen praktisch aus und macht die Gattung anfängertauglich. Hut weisslich bis blass cremefarben, Fleisch fest, mild, kaum madig. Alle Semmelstoppelpilz-Arten (auch H. repandum, H. rufescens) sind essbar; eine genaue Artbestimmung ist für die Küche nicht sicherheitskritisch. Stets gut durchgaren, ältere Stücke können leicht bitter sein.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt); Wikipedia','f'),
('hydnum_rufescens','Hauptzeit Aug–Okt (vereinzelt Juli und bis Nov), ca. 1–2 Wochen nach kräftigem Spätsommer-/Herbstregen bei 10–18 °C. Erscheint oft truppweise und in Hexenringen; relativ witterungsrobust und lange haltbar, da kaum madig.','Eher saure bis neutrale, humose und moosige Waldböden, frisch bis mässig feucht; oft an moosreichen, lichten Stellen.','Mykorrhiza-Partner von Laub- und Nadelbäumen (Buche, Eiche, Birke, Fichte). Typisch in lichten Wäldern, an grasig-moosigen Böschungen, Wegrändern und Lichtungen. Zeigerstandort: moosige Partien unter Buchen oder Fichten.','anfaenger','Stoppelpilze sind eine sichere Anfängergruppe: orange- bis rotbrauner, oft etwas trichteriger Hut und – statt Lamellen oder Röhren – weiche, weisslich-creme Stacheln (Stoppeln) an der Hutunterseite. Keine giftigen Doppelgänger; das Stachelmerkmal schliesst Verwechslung mit gefährlichen Lamellenpilzen aus. H. rufescens ist kleiner und kräftiger gefärbt als der Semmelstoppelpilz (H. repandum). Fleisch mild, im Alter leicht bitterlich – jüngere Exemplare bevorzugen. Madenfrei, daher gut zum Trocknen.','123pilze.de; SwissFungi (WSL); DGfM; Breitenbach/Kränzlin Pilze der Schweiz','f'),
('hygrophorus_eburneus','Hauptzeit September–November; erscheint einige Tage bis ~2 Wochen nach ergiebigem Herbstregen bei kühlem Wetter (ca. 6–14 °C), oft truppweise unter Buchen.','Kalkreiche, basenreiche Laubwaldböden; bevorzugt frische, gut mit Buchen-Laubstreu versorgte Standorte.','Mykorrhizapilz vor allem an Rotbuche (Fagus sylvatica) in kalkreichen Buchen- und Laubmischwäldern. Zeigerstandort sind kalkhaltige Buchenwälder (Buchen-Kalkwälder).','experte','Der Elfenbein-Schneckling hat einen rein elfenbeinweissen, stark schleimig-glitschigen Hut, weisse, weit herablaufende, dicke Lamellen und einen schmierigen Stiel; mild, aber kulinarisch nur mässig und schleimig (bedingt essbar). ACHTUNG – im selben Buchen-Kalkwald wachsen tödlich giftige weisse Pilze: weisse Trichterlinge (Clitocybe, Muscarin) und weisse Wulstlinge/Knollenblätterpilze (Amanita: Scheide, Ring). Wegen dieser lebensgefährlichen weissen Doppelgänger nur für erfahrene Sammler; im Zweifel den auffällig dicken Schleim, die weit herablaufenden Lamellen und das Fehlen von Scheide/Ring prüfen.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt); Wikipedia','f'),
('hygrophorus_hypothejus','Ausgesprochener Spätherbst- bis Winterpilz, Hauptzeit Oktober bis Dezember (teils bis in milde Januartage). Braucht die ersten Nachtfröste als Auslöser - schiebt erst nach Kälteeinbruch, oft wenn die meisten anderen Pilze schon durch sind. Nach Frostnächten plus etwas Feuchtigkeit erscheint er gesellig in Trupps unter Föhren.','Saure, magere Sandböden. Wärmebegünstigte, lichte Föhrenstandorte; meidet Kalk und nährstoffreiche Lagen.','Mykorrhiza-Partner der Wald-Föhre/Kiefer (Pinus sylvestris). Wächst am Boden in lichten Kiefernwäldern, an Wegrändern, auf Heideflächen und in der Nadelstreu - praktisch immer im direkten Wurzelbereich von Kiefern.','mittel','Kennzeichnend sind der schleimig-klebrige, oliv-braune Hut, die gelblichen, etwas herablaufenden Lamellen und der gelbliche, oben oft beringt wirkende, schmierige Stiel - alles bei kühler Spätsaison unter Kiefern. Abzugrenzen ist der Natternstielige Schneckling (Hygrophorus olivaceoalbus) mit weisslichen Lamellen und braun genattertem Stiel; giftige Doppelgänger gibt es in der Gruppe nicht, dennoch Schnecklinge nur bei sicherer Gattungskenntnis sammeln.','Recherche-Angabe geprüft via WebSearch (Frost-Auslöser, Kiefern-Mykorrhiza, saurer Sandboden, Verwechslung Natternstieliger Schneckling bestätigt; pilzfinder.de, mushroom-toxin.de)','f'),
('hygrophorus_marzuolus','Sehr früh im Jahr: Hauptzeit Feb–April (lagenabhängig bis Mai), oft direkt am ausapernden Schneerand. Erscheint nach Schneeschmelze und ersten milderen Tagen bei knapp über 0 bis ca. 8 °C; wächst langsam und schubweise über mehrere Wochen, häufig noch halb von Laub/Schnee bedeckt.','Bevorzugt kalkhaltige, humose Bergwaldböden; frisch, an eher kühl-schattigen Nordhängen. Lagen meist ca. 300–1500 m.','Mykorrhiza-Partner von Nadelbäumen, vor allem Weisstanne (Abies alba) und Fichte (Picea abies), auch Kiefer; teils unter Rotbuche im Bergmischwald. Zeigerstandort: kalkreiche Tannen-/Fichten-Bergwälder, oft in Moos- und Nadelstreu nahe Schneeresten, der Pilz drückt sich häufig nur halb durch die Streu.','mittel','Fleischiger, robuster Schneckling mit anfangs weisslichem, später grau bis schiefergrau geflecktem, schmierig-glattem Hut, weissen, dicklichen, weit stehenden Lamellen und weissem Fleisch. Wächst fast verborgen unter Laub/Nadelstreu – auf kleine Erdaufwölbungen achten. Guter Speisepilz, aber zur Erscheinungszeit (Vorfrühling) kaum Verwechslungs-Konkurrenz; dennoch graue Hutfarbe, weisse Lamellen und Tannen-/Kalkstandort gemeinsam prüfen. Nicht mit grauen Ritterlingen verwechseln. Standorttreu: gute Stellen jährlich wieder absuchen.','123pilze.de; SwissFungi (WSL); DGfM; Breitenbach/Kränzlin Pilze der Schweiz','f'),
('hypholoma_capnoides','Saprob auf Nadelholz, Hauptzeit September bis November, in milden Wintern bis Februar/März an frostfreien Tagen. Erscheint büschelig nach feuchten Phasen im Spätherbst; verträgt leichten Frost und schiebt oft noch, wenn das Laubwald-Aufkommen vorbei ist.','Kein Mykorrhiza-Pilz - Holzzersetzer ohne Bodenbindung; wächst direkt auf morschem Nadelholz unabhängig vom Bodentyp.','Büschelig auf Stümpfen und liegendem Totholz von Nadelbäumen, bevorzugt Fichte und Kiefer. Typisch an vermoosten Stubben in Nadel- und Mischwäldern.','experte','Sichere Merkmale: graue bis graubraune (nie gelbe oder grüne) Lamellen, milder Geschmack und das Wachstum auf Nadelholz. Strikt abzugrenzen vom giftigen Grünblättrigen Schwefelkopf (Hypholoma fasciculare), der oft am selben Stumpf wächst, aber schwefelgelbe bis grünliche Lamellen und einen bitteren Geschmack hat. Im Zweifel Lamellenfarbe und Bitterkeit prüfen - nur zweifelsfrei graublättrige, milde Büschel mitnehmen.','Recherche-Angabe geprüft via WebSearch (graue Lamellen + milder Geschmack als Trennung zum giftigen H. fasciculare, Nadelholz-Substrat, Spätherbst/Winter bestätigt; fungiversum.de, gizbonn.de, dikarbion.eu)','f'),
('infundibulicybe_geotropa','Spätsommer bis Spätherbst: vereinzelt ab Juli, Hauptzeit September–November, manchmal bis in den frühen Winter. Schiebt nach den herbstlichen Regenfällen, oft viele Fruchtkörper gleichzeitig.','Bevorzugt feuchte, kalkhaltige Böden in Laub- und Mischwäldern sowie an Waldrändern und auf Wiesen.','Waldränder, lichter Misch- und Laubwald, Waldwiesen, Lichtungen, Parkanlagen und Wegränder. Wächst gern in auffälligen Hexenringen oder Reihen mit oft 50+ Fruchtkörpern; grosse, trichterförmige Hüte gut sichtbar.','mittel','An Waldrändern, auf Waldwiesen und in lichtem Laub-/Mischwald nach den auffälligen Hexenringen/Reihen Ausschau halten; die grossen, hellen Trichterhüte sind aus Distanz erkennbar – einen Ring gefunden, lohnt das Absuchen der ganzen Formation.','Mykologisch plausibel bestätigt (Infundibulicybe geotropa, Mönchskopf): Saison ab Juli, Schwerpunkt September–November; feuchte kalkhaltige Böden, Waldränder/lichter Wald/Wiesen; bildet grosse, weithin sichtbare Hexenringe; grosse trichterförmige Hüte. Quellen: Wikipedia (Mönchskopf), pilzkurse.com, digital-nature.de. Unverändert übernommen.','t'),
('infundibulicybe_gibba','Sommer- bis Herbstpilz, Hauptzeit etwa Juni/Juli bis Oktober. Erscheint einzeln bis gesellig nach durchdringenden Sommerregen in der Laubstreu; reagiert recht zügig auf Niederschlag in warmen, feuchten Phasen.','Kein Mykorrhiza-Pilz - Streuzersetzer; auf Laub- und Nadelstreu frischer bis mässig nährstoffreicher Waldböden, ohne enge Bodentyp-Bindung.','Saprob in der Streuschicht von Laub-, Nadel- und Mischwäldern, an Waldrändern, Wegböschungen und auf Lichtungen. Wächst gern dort, wo sich Laub und Nadeln am Boden sammeln.','experte','Erkennbar am ockerbräunlichen, trichterig vertieften Hut mit kleinem Buckel im Zentrum, den weisslichen, weit herablaufenden Lamellen und dem deutlichen, oft mehlartigen Geruch. Vorsicht: Unter den Trichterlingen gibt es kleine, rein weisse, stark bis tödlich giftige Arten (muscarinhaltige Clitocybe) - Trichterlinge generell nur bei zweifelsfreier Artbestimmung sammeln. Sensible Personen vertragen die Art zudem nicht immer, daher nur klein und im Mischgericht.','Recherche-Angabe geprüft via WebSearch (Streuzersetzer Laub-/Nadelwald, Saison Jun-Okt, Hinweis auf giftige Trichterling-Verwechsler und mögliche Unverträglichkeit bestätigt; Wikipedia, pilzbuch-pilzwelten.de, 123pilzsuche.de)','f'),
('kuehneromyces_mutabilis','Mehrere Schübe von Mai bis November, Hauptwellen im Frühjahr und Herbst. Fruchtet wenige Tage bis ~1 Woche nach feuchtem Wetter bei milden 10–18°C; nach kühlen, regnerischen Perioden besonders ergiebig. Anders als Mykorrhizapilze nicht streng saisonal — bei Feuchte ganzjährig in der wärmeren Hälfte möglich.',NULL,'Büschelig auf und um morsche Laubholz-Stümpfe und liegendes Totholz, bevorzugt Buche, Birke, Weide, Erle, Linde; nur selten Nadelholz. Feuchte Laub- und Mischwälder, Bachränder, schattige morsche Stümpfe.','anfaenger',NULL,'fact-checked: saprob auf Laubholz-Totholz, mehrere Schübe Frühjahr+Herbst, plausibel — unverändert','t'),
('lactarius_deliciosus','Hauptsaison Spätsommer bis Herbst, ca. August–Oktober (in milden Lagen bis November/erster Frost). Fruchtkörper 1–2 Wochen nach ergiebigem Spätsommer-/Herbstregen bei milden Temperaturen; nach den ersten kühleren, feuchten Herbsttagen schiebt er zuverlässig.',NULL,'Mykorrhiza streng mit Kiefer (v.a. Waldkiefer). In Kiefern-, Nadel- und Mischwäldern mit Kiefernbeteiligung; an lichten Stellen, Waldweg- und Waldrändern, oft in Gras/Moos unter jüngeren Kiefern. In CH typisch auf sandig-kalkigen Föhrenstandorten.','mittel',NULL,'fact-checked: Kiefern-Mykorrhiza, Spätsommer/Herbst, plausibel — unverändert','t'),
('lactarius_deterrimus','August bis Oktober, Hauptschub September bis zum ersten harten Frost (oft November). Erscheint nach feuchtem Spätsommer-/Herbstwetter; die kühl-feuchten Herbsttage lösen den Hauptschub aus. Oft etwas früher und häufiger als der Edel-Reizker.',NULL,'Mykorrhiza eng an Fichte gebunden. In Fichten- und fichtenreichen Nadel-/Mischwäldern; truppweise auf moosigem oder nadelbedecktem Boden, gern an Wegrändern, Lichtungen und unter jüngeren Fichten. In CH bis in höhere Lagen einer der häufigsten Reizker.','anfaenger',NULL,'fact-checked: Fichten-Mykorrhiza, Herbst, plausibel — unverändert','t'),
('lactarius_rufus','Hauptzeit Aug–Okt (bis Nov), ca. 1–2 Wochen nach ergiebigem Spätsommer-/Herbstregen bei 10–16 °C. Erscheint oft in grossen Trupps und über mehrere Wochen; einer der häufigsten Milchlinge saurer Nadelwälder.','Ausgesprochen saure, nährstoffarme, oft sandig-torfige oder moorige Böden; frisch bis feucht. Häufig in Heidelbeer- und Torfmoos-Beständen.','Mykorrhiza-Partner von Nadelbäumen (Kiefer, Fichte, Tanne) und Birke. Zeigerstandort: bodensaure Kiefern-/Fichtenwälder, Moorränder, oft zwischen Heidelbeere (Vaccinium) und Torfmoos (Sphagnum). Zeigerpflanzen: Heidelbeere, Drahtschmiele, Torfmoos deuten den passenden sauren Standort an.','mittel','Rotbrauner, trichterig vertiefter Hut mit kleinem Buckel (Papille), bräunlicher Stiel; beim Anschneiden tritt reichlich weisse, unveränderliche Milch aus, die sehr scharf (paprika-/pfefferscharf) schmeckt – daher Name Paprikapilz. Nur bedingt essbar: roh giftig/scharf, essbar erst nach Abbrühen/gründlichem Garen, meist als Mischpilz oder Würzpilz. Scharfe Milch + saurer Nadelwald-Standort = gutes Erkennungsmerkmal. Verwechselbar mit anderen rotbraunen Milchlingen; mild schmeckende Milchlinge nicht damit verwechseln. Geschmacksprobe (Milch auf die Zunge, danach ausspucken) hilft bei der Abgrenzung.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt BLV Handbuch Pilze','f'),
('lactarius_salmonicolor','Hauptzeit September–Oktober (vereinzelt ab Juli bis November), schubweise ca. 1–2 Wochen nach ergiebigem Landregen bei milden 10–18 °C. Erscheint nach feucht-warmen Spätsommerwochen oft gleichzeitig mit anderen Edelreizkern; auf höheren Tannenlagen entsprechend später.','Frische, basen- und nährstoffreiche, eher kalkhaltige Waldböden; mässig feucht, gut durchlüftet. Meidet stark saure, magere Standorte.','Mykorrhiza ausschliesslich mit der Weisstanne (Abies alba); in Tannen- und Tannen-Buchenwäldern, gern an feuchteren, moosigen Stellen und Hangfüssen. Zeiger: reine Tannenbestände bzw. tannenreicher Bergmischwald.','mittel','Auf orange gezonten Hut mit eingerolltem Rand und auf die orange Milch achten, die langsam weinrötlich verfärbt – ohne Grünfleckung. Nur unter Weisstanne suchen; ohne Tanne in der Nähe ist es nicht der Lachsreizker. Speisewert mässig (kann leicht bitter sein), am besten jung und kräftig anbraten. Verwechslung mit anderen orangemilchenden Reizkern (Edelreizker-Gruppe) ist harmlos, aber Standort und Milchfarbe trennen sicher.','123pilze, SwissFungi (Verbreitung Abies alba), DGfM; Pilzführer Gminder/Laux','f'),
('lactarius_semisanguifluus','Spätsommer bis Herbst, Hauptzeit August bis Oktober/November. Schiebt gesellig nach ergiebigen Spätsommer- und Herbstregen im Kiefernwald; nutzt feucht-milde Phasen nach längeren Niederschlägen.','Saure, magere, eher trockene Sandböden in wärmebegünstigten Kiefernlagen; meidet schwere und stark nährstoffreiche Böden.','Mykorrhiza-Partner der Kiefer/Föhre (Pinus). Wächst am Boden in lichten Kiefernwäldern, an Waldrändern und Wegböschungen, gern auf moosig-grasigen Stellen im Wurzelbereich der Kiefern.','experte','Reizker erkennt man an der Milch, die hier zunächst orange austritt und sich rasch über weinrot zu weinbraun verfärbt, sowie an grünlichen Verfärbungen am Hut. Innerhalb der Milchlinge gibt es viele scharf schmeckende, ungeniessbare bis unverträgliche Arten - sichere Reizker-Bestimmung über Milchfarbe, Milchverfärbung und Nadelbaum-Partner ist Pflicht. Sehr ähnlich ist der Fichtenreizker (L. deterrimus); zur Unterscheidung auf festeres Fleisch, nie schleimigen Hut und Kiefern als Partner achten.','Recherche-Angabe geprüft via WebSearch (Kiefern-Mykorrhiza auf sauren Sandböden, Milchverfärbung orange->weinrot->weinbraun, Abgrenzung zu L. deterrimus bestätigt; Wikipedia Edel-Reizker, pilzbuch-pilzwelten.de, pilz-baden.ch)','f'),
('lactarius_subdulcis','Sommer bis Spätherbst, Hauptzeit Juli bis Oktober/November. Erscheint gesellig in kleinen Grüppchen nach Regenphasen unter Buchen; recht treuer Begleiter feuchter Buchenwald-Abschnitte.','Frische bis feuchte, eher saure Laubwaldböden; an Bodentyp wenig wählerisch, solange Buchen als Partner vorhanden sind.','Mykorrhiza-Partner der Buche (Fagus). Wächst am Boden in Buchen- und Buchenmischwäldern, oft im Moos oder in der Laubstreu direkt unter Buchen; charakteristisch ein wolliges Myzelbüschel an der Stielbasis.','experte','Kleiner, rotbrauner Milchling mit weisser, unveränderlicher Milch, die erst süsslich, dann leicht bitter schmeckt, und feucht-fettig glänzendem Hut. Nur bedingt essbar und geschmacklich schwach, daher höchstens als Mischpilz. Achtung: zahlreiche zierliche, ähnlich gefärbte Milchlinge sehen fast gleich aus, einige davon scharf und ungeniessbar - Milchlinge generell nur mit sicherer Artkenntnis sammeln (Milchfarbe, Geschmack, Partnerbaum prüfen).','Recherche-Angabe geprüft via WebSearch (Buchen-Mykorrhiza, weisse Milch süsslich-dann-bitter, Myzelbüschel an Stielbasis, nur bedingt essbar/Mischpilz, viele ähnliche Milchlinge bestätigt; Wikipedia, pilzbuch-pilzwelten.de, tintling.com)','f'),
('lactarius_torminosus','Hauptzeit August–Oktober (ab Juli möglich), schubweise rund 1–2 Wochen nach kräftigem Regen bei 12–18 °C. Tritt in feucht-milden Spätsommer-/Herbstphasen oft truppweise unter Birken auf.','Saure, eher trockene bis mässig feuchte, magere Böden; auch auf verdichteten, sandigen Wegrändern und Ruderalflächen.','Mykorrhiza mit Birke (Betula); an Birken in Wäldern, an Wald- und Wegrändern, in Parks und Gärten. Zeiger: junge Birken auf saurem, lichtem Boden.','experte','Kennzeichnend ist der stark zottig-bärtige, eingerollte Hutrand und die blass rosa-orange Hutfarbe; die weisse Milch ist scharf und bleibt weiss. Nur bedingt essbar – roh giftig/magen-darm-reizend, in einigen Regionen nur nach gründlichem Abbrühen verwendet; für Einsteiger nicht empfohlen. Vom essbaren Lachs-/Edelreizker durch weisse (nicht orange) Milch und den bärtigen Rand sicher zu trennen. Im Zweifel stehen lassen.','123pilze, DGfM (bedingt essbar/roh giftig), SwissFungi; Pilzführer Laux','f'),
('lactarius_volemus','Sommer bis Herbst, am häufigsten Juli–September, Spitzen an den wärmsten Augusttagen. Fruchtet bevorzugt bei sommerlicher Wärme einige Tage nach Regen — eher ein Wärmepilz als ein Spätherbstpilz.',NULL,'Mykorrhiza mit Laub- und (seltener) Nadelbäumen, klar bevorzugt Buchen-/Laubwald, gern bei Eiche und Buche. Eher Hügel- und Bergland; im Flachland seltener. Lichte, ältere Laubwälder.','experte',NULL,'fact-checked: Sommer/Herbst-Wärmepilz, Laubwald-bevorzugt, Hügel-/Bergland, plausibel (RL3-Art, hohe difficulty vertretbar) — unverändert','t'),
('laetiporus_sulphureus','Einjährige Fruchtkörper von (April/)Mai bis Oktober, Schwerpunkt spätes Frühjahr und Frühsommer. Erscheint nach warm-feuchten Phasen; junge, frische Konsolen bilden sich rasch bei Wärme und Luftfeuchte (Guttationstropfen bei feuchtem Wetter).',NULL,'Bevorzugt Laubbäume: Eiche, Robinie, Weide, Pappel und Obstbäume (selten Nadelholz wie Lärche). Am Stamm, an Stammfuss, Starkästen, Schnitt-/Astwunden und Schnittflächen — oft in grösserer Höhe; dachziegelartig in Gruppen. Auch in Parks, Alleen, an Einzelbäumen.','anfaenger',NULL,'fact-checked: Saison ab Mai mit Frühsommer-Schwerpunkt bestätigt, Laubholz-Wirte korrekt, anfaenger plausibel — unverändert','t'),
('leccinum_aurantiacum','Fruchtkörper von Juni bis Oktober (selten ab Mai). Erscheint nach ausreichenden Sommer-/Herbstniederschlägen bei mildem Wetter — typischer Sommer- bis Herbstpilz, oft schon im Hochsommer.',NULL,'Mykorrhiza streng an Espe/Zitterpappel (Populus tremula) gebunden, generell bei Pappeln. Bei einzelnen Pappel-/Espengruppen, an Waldrändern, Lichtungen, in Mooren, gern an feuchteren, halblichten Stellen. Erscheint auch innerhalb von Nadel-/Mischwäldern — dort aber stets bei eingestreuten Espen/Pappeln, deren Wurzeln er besiedelt (nicht mit Fichte/Tanne vergesellschaftet).','mittel',NULL,'korrigiert: L. aurantiacum s.str. ist Espen-/Pappel-Mykorrhiza, NICHT mit Fichte/Tanne vergesellschaftet. Ursprungstext ''auch in Fichten-Tannen-Wäldern mit eingestreuten Espen'' war missverständlich (las wie Nadelholz-Partner) — präzisiert: der Pilz folgt nur den eingestreuten Espen/Pappeln. Saison Juni–Okt korrekt.','t'),
('leccinum_pseudoscabrum','Fruchtkörper von Juni bis Oktober. Erscheint nach Sommer-/Herbstregen bei mildem Wetter; einer der frühen Röhrlinge, oft schon ab Frühsommer bei ausreichender Feuchte.',NULL,'Mykorrhiza mit der Hainbuche (Carpinus betulus). In hainbuchenreichen Laub- und Mischwäldern, an Waldrändern, Strassenrändern, in Parkanlagen und Alleen — immer in unmittelbarer Nähe von Hainbuchen.','mittel',NULL,'fact-checked: Hainbuchen-Mykorrhiza korrekt, Juni–Okt, mittel plausibel — unverändert','t'),
('leccinum_versipelle','Frühstarter ab Juni (in milden Jahren schon Mai) bis Oktober; Hauptschub August–Oktober. Bei feucht-mildem Sommerklima 1–2 Wochen nach ergiebigem Regen oft kurzzeitiges Massenvorkommen.','Bevorzugt eher saure, durchlässige Böden; gedeiht auf sandig-humosen bis moorigen Standorten in Birkennähe.','Strikte Mykorrhiza mit Birke (Betula pendula/pubescens). Suche gezielt bei einzelstehenden oder lichten Birken, Birken-Waldränder, Heide- und Moorrandlagen, bemooste lichte Stellen.','mittel','Erst die Wirtsbaumart suchen, nicht den Pilz: lichte Birken, Birken-Waldränder und Moorränder absuchen. 1–2 Wochen nach ergiebigem Regen erscheint er bei Birken oft truppweise.','Mykologisch plausibel und per WebSearch bestätigt (de.wikipedia.org Birken-Rotkappe / Vielverfärbender Birkenpilz, pilzlexikon.eu): obligate Birken-Mykorrhiza, Frühstarter ab Mai/Juni, Hauptsaison August–Oktober. Keine Korrektur nötig.','t'),
('lepista_glaucocana','Herbst- bis Frühwinterpilz, Hauptzeit Oktober bis Dezember, bis zum ersten harten Frost. Erscheint oft in Reihen, Gruppen oder Hexenringen nach feuchten Herbstwochen; einer der spätesten Speisepilze der Saison.','Nährstoffreiche, humose, oft kalkhaltige Böden; bevorzugt gut versorgte Lagen in Wald, Park und Garten.','Kein Mykorrhiza-Pilz - Folgezersetzer auf nährstoffreichem Boden; in Laub-, Nadel- und Auwäldern, Parks, Gärten und an Wegrändern, gern auf Laub- und Kompostanhäufungen.','experte','Jung ein guter Speisepilz, erkennbar am blass ockerfarbenen Hut mit lila bis graublauem Schimmer (heller und weniger violett als der Violette Rötelritterling) und gedrängten, im Alter rötlich-ockerlichen Lamellen. Verwechslungsgefahr besteht mit giftigen Arten anderer Gattungen, insbesondere dem giftigen Wohlriechenden Trichterling (Clitocybe) - daher Hutfarbe, Lamellenfarbe und Geruch genau prüfen und nur bei sicherer Bestimmung sammeln.','Recherche-Angabe geprüft via WebSearch (Folgezersetzer nährstoffreicher Boden, Spätherbst bis Frost, blass ocker-lila Hut, Verwechslung mit giftigem Wohlriechenden Trichterling bestätigt; pilzbuch-pilzwelten.de, mykopedia.org, 123pilzsuche.de)','f'),
('lepista_nuda','Spätherbst-Pilz: September bis in den Spätfrost hinein, Hauptsaison Oktober–November. Erscheint zuverlässig nach den ersten kühlen, feuchten Herbsttagen; verträgt leichte Fröste.','Folgezersetzer auf nährstoffreicher, humoser Laub- und Nadelstreu; gedeiht in dicker Falllaubschicht und auf Kompost.','Saprophyt (Folgezersetzer, keine Mykorrhiza). Laub- und Laubmischwälder, auch Nadelwald, Auwald, Hecken, Gärten und Komposthaufen. Wächst gehäuft in Hexenringen und Reihen in der Laubstreu.','anfaenger','Einer der letzten Herbstpilze – erst suchen, wenn die ersten Nachtfröste durch sind. Dicke Laubstreu, Heckenränder und Komposthaufen abgehen; auf Hexenringe und Reihen in der violetten Streu achten.','Mykologisch plausibel und per WebSearch bestätigt (de.wikipedia.org Violetter Rötelritterling, fundkorb.de, digital-nature.de): Saprophyt/Folgezersetzer, ausgeprägter Spätherbstpilz Oktober–November mit leichter Frosttoleranz. Keine Korrektur nötig.','t'),
('lepista_saeva','Späte Art: Hauptzeit Oktober–November (bis in milde Dezembertage), oft erst nach den ersten kühlen Nächten und Nebel-/Tauphasen, ca. 1–2 Wochen nach Regen bei 5–12 °C. Verträgt leichte Nachtfröste und erscheint in Hexenringen.','Nährstoffreiche, kalkhaltige bis neutrale Wiesen- und Weideböden; mässig feucht, gut gedüngte Grasflächen bevorzugt.','Kein Mykorrhizapilz – Streu-/Bodensaprobiont auf Wiesen, Weiden, in Parks, an Waldrändern und Lichtungen; bildet auffällige Hexenringe. Zeiger: ältere, ungespritzte Magerwiesen und Viehweiden.','mittel','Markant ist der lila bis violett gefärbte, faserige Stiel unter einem blass lederbraunen, kahlen Hut mit blassrosa-lila, gedrängten Lamellen; Geruch angenehm. Auf Wiesen wachsend, nicht im Wald – das hilft, ihn von violetten Wald-Schleierlingen (Cortinarius, teils giftig) zu trennen, die ein Cortina-Velum und rostbraunes Sporenpulver haben. Lepista hat kein Velum und blassrosa Sporenpulver. Spät im Jahr in Ringen suchen.','123pilze, DGfM, SwissFungi; Pilzführer Gminder','f'),
('lycoperdon_echinatum','Juli bis Oktober. Erscheint nach ergiebigen Sommer- und Frühherbstregen bei feucht-warmer Witterung, oft schubweise eine knappe Woche nach durchdringendem Landregen. Beste Funde nach mehreren feuchten Tagen im schattig-humosen Buchenwald.','Bevorzugt kalkhaltige, basenreiche und humusreiche Waldböden; gedeiht auf der Laubstreu- und Humusauflage, nicht auf Holz.','Saprobiont im Laub- und Buchenwald auf Humus und Falllaub, gern an krautreichen, kalkbeeinflussten Stellen. Zeigerpflanzen kalkreicher Buchenwälder (z.B. Waldmeister, Bingelkraut) markieren gute Standorte.','experte','Nur ganz junge, innen rein weiße Fruchtkörper sind essbar; sobald das Innere gelblich oder olivbraun wird (Sporenreife), ist der Pilz ungenießbar. JEDEN Stäubling vor der Verwendung längs halbieren: ist innen eine Hutkappe, Lamellenansatz oder eine gegliederte Silhouette zu sehen, handelt es sich um ein lebensgefährliches Knollenblätterpilz-Ei (Amanita) und niemals um einen Stäubling. Der Igel-Stäubling ist an den langen, oft an der Spitze gebogenen, in Büscheln zusammenneigenden Stacheln erkennbar.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt, Der grosse BLV Pilzführer','f'),
('lycoperdon_perlatum','Lange Saison Juli (vereinzelt Juni) bis November; Schwerpunkt Spätsommer/Herbst. Erscheint einige Tage nach Regen, witterungsabhängig in grosser Zahl.','Bodensaprophyt auf humoser Streu und Waldböden; anspruchslos, auf magerem Weide- und Brachboden ebenso wie im Wald.','Saprophyt am Boden, häufig truppweise. Am häufigsten in Nadel- und Nadelmischwäldern, auch reine Laubwälder; zudem Waldränder, Weiden, trockene Wiesen und Brachen, im Gebirge.','anfaenger','Truppweise an Waldwegrändern und auf bemoosten Waldböden; einige Tage nach Regen erscheinen ganze Gruppen. Junge, innen rein weisse Exemplare beachten.','Mykologisch plausibel (Standard-Lexikonwissen): häufiger Bodensaprophyt, lange Saison Juli–November mit Herbstschwerpunkt, Nadel-/Mischwald-Schwerpunkt. Keine Korrektur nötig.','t'),
('lyophyllum_decastes','Lange Saison mit Schwerpunkt September–November, kleinere Schübe schon im Frühjahr (April–Mai) möglich. Erscheint büschelig ca. 1–2 Wochen nach Regen bei 10–18 °C, gern auf gestörten, frisch bearbeiteten Böden.','Lockere, humusreiche, nährstoffreiche Böden; frische bis feuchte, oft gestörte Standorte (Erdaufschüttungen, Wegränder).','Saprobiont – kein Baumpartner; in dichten Büscheln an Wegrändern, auf Wiesen, in Laub- und Mischwäldern, Parks und auf Erdaufschüttungen. Zeiger: frisch aufgeschütteter oder verdichteter, humoser Boden.','experte','Wächst in dichten, verwachsenen Büscheln mit grau- bis ockerbraunen, glatten Hüten, weisslichen gedrängten Lamellen, faserigem Stiel ohne Ring und mildem Geruch/Geschmack. Achtung: büschelig wachsende Arten sind heikel – Verwechslung mit dem giftigen Riesen-Rötling (Entoloma sinuatum, rosa Sporenpulver) und anderen ist möglich. Sporenpulver weiss prüfen und nur bei sicherer Bestimmung sammeln; für Anfänger nicht geeignet.','123pilze, DGfM, SwissFungi; Pilzführer Laux/Gminder','f'),
('macrolepiota_mastoidea','Hauptzeit August–Oktober (bis November), einzeln bis in kleinen Gruppen ca. 1–2 Wochen nach ausgiebigem Regen bei 12–20 °C. Bevorzugt warme Spätsommer-/Herbstphasen an lichten, grasigen Stellen.','Kalkhaltige, nährstoffreiche, eher trocken-warme Böden; lichte, grasige Standorte.','Saprobiont der Streu; in lichten Laub- und Mischwäldern, an Wald- und Wegrändern, auf Heiden, in Parks und Gärten. Zeiger: warme, kalkreiche Säume und Lichtungen.','mittel','Schirmpilz-Typ mit deutlich vorgezogenem, spitzem Buckel („Zitze") auf hell genattertem Hut, schlankem genattertem Stiel und verschiebbarem Ring; Fleisch verfärbt sich kaum. Wie alle Riesenschirmlinge nur den grossen, hochwüchsigen Schirmling sammeln – kleine Schirmlinge (Lepiota) und der giftige Garten-Safranschirmling (Chlorophyllum) sind gefährliche Verwechsler. Auf den verschiebbaren Ring und die deutliche Zitze achten; Stielbasis ohne Knolle/Scheide.','123pilze, DGfM, SwissFungi; Pilzführer Gminder/Laux','f'),
('marasmius_oreades','Mai bis November, mehrere Schübe pro Jahr. Erscheint sehr zuverlässig direkt nach ergiebigem Regen, oft in Massen; bei feucht-warmer Witterung wiederholt.','Grasland-Saprophyt; gedeiht auf nährstoffarmen bis mittleren Wiesen- und Rasenböden, auch auf Magerwiesen.','Saprophyt im Gras. Wiesen, Weiden, Magerwiesen, Parks, Rasen in Gärten und grasige Wegränder, auch grasige Waldstellen. Wächst typisch in Hexenringen/Reihen — das Gras im Ring ist oft auffällig sattgrün.','anfaenger','Auf Hexenringe in der Wiese achten – das Gras im Ring leuchtet oft auffällig sattgrün. Reagiert sehr schnell auf Regen, daher 1–3 Tage nach einem Schauer die gleichen Wiesen erneut absuchen.','Mykologisch plausibel und per WebSearch bestätigt (de.wikipedia.org Nelken-Schwindling, pilzfinder.de, naturdetektive.at): Grasland-Saprophyt, Saison Mai–November in mehreren Schüben, charakteristische Hexenringe mit sattgrünem Gras. Keine Korrektur nötig.','t'),
('marone','Je nach Witterung Juni–November, Hauptschub September bis erste Novemberhälfte. Etwa 5–10 Tage nach kräftigem Regen; reagiert wie der Steinpilz rasch auf feucht-milde Bedingungen, in trockenen Lagen nur bei ausreichend Regen.','Bevorzugt bodensaure, eher magere Nadel- und Mischwaldböden; typisch in älteren Fichtenwäldern auf saurer Nadelstreu.','Mykorrhiza bevorzugt mit Fichte und Lärche, auch Buche, Eiche, Esskastanie. Charakterart bodensaurer Nadel- und Mischwälder; vor allem ältere Fichtenwälder, oft truppweise/in Massen.','anfaenger','Ältere, bodensaure Fichtenwälder gezielt absuchen; erscheint oft truppweise. Etwa 5–10 Tage nach kräftigem Regen losziehen; reagiert ähnlich rasch wie der Steinpilz auf feucht-milde Witterung.','Mykologisch plausibel und per WebSearch bestätigt (awl.ch, fungiversum.de, pilzbuch-pilzwelten.de): Mykorrhiza bevorzugt mit Fichte/Lärche (auch Buche/Eiche/Esskastanie), Hauptsaison Mitte September–November, vor allem ältere Fichtenwälder. Keine Korrektur nötig.','t'),
('maronenroehrling','Je nach Witterung Juni–November, Hauptschub September bis erste Novemberhälfte. Etwa 5–10 Tage nach kräftigem Regen; reagiert wie der Steinpilz rasch auf feucht-milde Bedingungen, in trockenen Lagen nur bei ausreichend Regen. (Boletus badius = Imleria badia, identisch mit Marone.)','Bevorzugt bodensaure, eher magere Nadel- und Mischwaldböden; typisch in älteren Fichtenwäldern auf saurer Nadelstreu.','Mykorrhiza bevorzugt mit Fichte und Lärche, auch Buche, Eiche, Esskastanie. Charakterart bodensaurer Nadel- und Mischwälder; vor allem ältere Fichtenwälder, oft truppweise/in Massen.','anfaenger','Ältere, bodensaure Fichtenwälder gezielt absuchen; erscheint oft truppweise. Etwa 5–10 Tage nach kräftigem Regen losziehen; reagiert ähnlich rasch wie der Steinpilz auf feucht-milde Witterung.','Mykologisch plausibel und per WebSearch bestätigt (awl.ch, fungiversum.de): identisch mit Marone (Imleria badia, syn. Boletus/Xerocomus badius). Fichten-/Lärchen-Mykorrhiza, Hauptsaison Mitte September–November. Keine Korrektur nötig.','t'),
('meripilus_giganteus','Hauptzeit Juli–Oktober (bis November), als grosse Rosette über mehrere Wochen am selben Stamm wachsend; Frischschub typischerweise nach feucht-warmen Phasen und Regen bei 14–22 °C. Erscheint mehrjährig wiederkehrend am gleichen Wurzelbereich.','Standort vom Wirtsbaum bestimmt; nährstoffreiche, feuchte Wald- und Parkböden im Wurzelbereich alter Laubbäume.','Saprobiont/Schwächeparasit – kein Mykorrhizapilz; wächst in grossen, fächerigen Büscheln an der Stammbasis und über den Wurzeln alter Buchen, auch an Eiche, Linde, Rosskastanie, in Wäldern und Parks. Zeiger: alte, kränkelnde Laubbäume und deren Wurzelanläufe.','anfaenger','Sehr auffällig und kaum zu verwechseln: riesige, fächerförmige Rosette aus vielen weich-fleischigen Hüten an der Basis alter Buchen; Unterseite mit feinen Poren (keine Lamellen), Fleisch verfärbt sich bei Druck/Schnitt schwärzlich. Nur ganz junge, zarte Randteile sind essbar (gekocht), ältere werden zäh und sind von mässigem Speisewert. Wegen Schwärzung und Poren leicht von Lamellenpilzen zu unterscheiden – ein guter Anfänger-Erkennungspilz, aber kein hochwertiger Speisepilz.','123pilze, DGfM, SwissFungi; Pilzführer Laux','f'),
('mitrophora_semilibera','Mitte März bis Mai. Frühjahrspilz; erscheint nach milden, regnerischen Phasen sobald die Böden sich erwärmen, typischerweise zur Zeit der Buschwindröschen- und Bärlauchblüte. Beste Funde in feuchten Auwäldern nach mildem, niederschlagsreichem Frühlingswetter.','Feuchte, nährstoff- und basenreiche, oft kalkhaltige Auen- und Lehmböden; liebt frische bis nasse, humose Standorte in Gewässernähe.','Saprobiont/Begleiter in Auwäldern, Ufergebüschen und Laubwald, bevorzugt unter Esche, Pappel und Ulme auf feuchtem Grund. Brennnessel-, Bärlauch- und Scharbockskraut-Fluren in Flussauen sind verlässliche Begleitvegetation.','experte','Wie alle Morcheln nur durchgegart und nie roh verzehren (roh giftig); kleine Mengen, da der Pilz Unverträglichkeiten auslösen kann. Kennzeichnend ist der nur zur Hälfte mit dem Stiel verwachsene, glockige Hut (unterer Hutrand frei abstehend). Gefährlichster Verwechsler ist die Frühjahrslorchel (Gyromitra esculenta) mit hirnartig gewundenem, nicht wabig-gekammertem Hut — sie ist roh tödlich giftig; im Zweifel den Längsschnitt prüfen (echte Morcheln/Käppchenmorchel sind innen vollständig hohl).','123pilze.de; SwissFungi (WSL); DGfM; Laux, Essbare Pilze und ihre giftigen Doppelgaenger','f'),
('morchelchampignon','Frühjahrspilz März–Mai (Mittelland früh, Gebirge bis zur Baumgrenze später). Schiebt, wenn die nächtliche Bodentemperatur stabil bei ~10–12°C liegt; ca. 3–4 Tage nach kräftigem Frühjahrsregen plus einigen milden, sonnigen Tagen.','Bevorzugt kalkhaltige, nährstoffreiche, humose und eher feuchte, aber gut durchlüftete Böden; typisch auf Auenböden und Schwemmland an Flussufern.','Saprophyt. Lichte Auen- und Laubwälder, gerne bei Esche, Ulme und Pappel; Flussufer-Lagen (in der CH z.B. Aare, Reuss, Emme, Limmat). Zeigerpflanzen: Esche, Bärlauch, Schlüsselblume, Buschwindröschen, Pestwurz.','experte','Frühjahrs-Auenwälder an Flussufern (Aare, Reuss, Emme, Limmat) auf kalkhaltigem Boden absuchen. An Zeigerpflanzen orientieren: Esche, Bärlauch, Schlüsselblume, Buschwindröschen, Pestwurz. Losziehen, wenn nach Frühjahrsregen einige milde, sonnige Tage folgen.','Mykologisch plausibel und per WebSearch bestätigt (pilzkurse.com, awl.ch Speisemorchel, myk.univie.ac.at): Frühjahrspilz März–Mai (NICHT Herbst), Saprophyt in Auen-/Laubwäldern bei Esche/Ulme/Pappel auf kalkhaltigem Boden. Saison korrekt als Frühjahr angegeben. Keine Korrektur nötig.','t'),
('morchella_elata','Frühjahr März–Mai (in höheren Lagen bis Juni), kurz nach der Schneeschmelze an den ersten warmen, milden Tagen. Schub kommt nach feucht-mildem Wetter, wenn der Boden sich erwärmt; oft 1–2 Wochen nach gründlicher Durchfeuchtung. Erscheint früher als die Speisemorchel.',NULL,'Saprobiont (kein Mykorrhiza-Pilz). Auwälder, Laub-/Mischwälder, Waldränder, Böschungen, Gebüsch in Parks. Gerne unter Esche, Pappel, Ulme, Eiche, Hainbuche, Birke, Weide. Auch auf Holzlagerplätzen, Brandstellen, Kahlschlägen und gemulchten Flächen in Gärten/Siedlungen.','experte',NULL,'Recherche + Faktencheck (mykologische Quellen)','t'),
('paralepista_flaccida','August bis November. Spätsommer- bis Spätherbstpilz; erscheint nach den ersten kühleren, feuchten Herbstphasen und kräftigem Landregen, oft gesellig in Reihen und Hexenringen. Verträgt erste leichte Nachtfröste.','Frische, humusreiche Wald- und Streuböden; sowohl auf saurem Nadelstreu als auch auf neutralem bis kalkhaltigem Laubhumus.','Streuzersetzer (Saprobiont) in Nadel-, Laub- und Mischwald, auf dicker Nadel- und Laubstreu, an Wegrändern und in Parkanlagen; wächst gern gesellig in Büscheln, Reihen und Hexenringen.','experte','Nur jung und stets gut durchgegart geniessbar (roh unverträglich), Geschmack mittelmäßig — eher Sammelpilz für Kenner. Erkennungsmerkmale: fuchsig orangebrauner, im Alter tief trichterförmiger Hut, am Stiel herablaufende Lamellen und oft hygrophan ausblassende Färbung. Achtung: In der Gruppe weisser und blasser Trichterlinge (Clitocybe) gibt es stark muskarinhaltige, giftige Arten — kleine, rein weisse Trichterlinge auf Wiesen/Wegrändern niemals mit diesem Pilz verwechseln; im Zweifel stehen lassen.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt, Der grosse BLV Pilzführer','f'),
('parasol','Hauptsaison Juli–November, Schwerpunkt Spätsommer/Herbst. Schübe folgen einige Tage bis ~1–2 Wochen nach ergiebigem Regen bei noch warmem Wetter. In trockenen Sommern erst ab dem ersten kräftigen Spätsommer-/Herbstregen.',NULL,'Saprobiont. Lichte Buchen-, Eichen- und Mischwälder mittleren Alters, sehr oft an Waldrändern, auf Lichtungen und Waldwegen; auch Magerwiesen, Weiden, Parks und Gärten. Steht meist gut sichtbar einzeln oder in Hexenringen an offenen, sonnigen Lagen.','anfaenger',NULL,'Recherche + Faktencheck (mykologische Quellen)','t'),
('phallus_impudicus','Hauptzeit Juli–Oktober, einzelne Exemplare schon ab Juni; das Stadium «Hexenei» erscheint schubweise einige Tage nach feucht-warmer Witterung und reckt sich bei 15–20 °C oft innert weniger Stunden zum reifen Fruchtkörper – die Reife ist also extrem schnell.','Humusreiche, nährstoffreiche, gut durchfeuchtete Böden; weitgehend bodenvag, sowohl auf saurem als auch kalkhaltigem Untergrund, gern bei morschem Holz im Boden.','Saprobiont (kein Mykorrhiza-Partner) auf vergrabenem Totholz und Holzhäcksel; in Laub-, Nadel- und Mischwald, Auwald, Parkanlagen und Gebüschen, häufig nahe Stümpfen und unter Brennnesseln/Holunder als Nährstoffzeiger.','mittel','Der reife Pilz ist am penetranten Aasgeruch und der grünlich-schleimigen, fliegenbesetzten Hutkappe schon aus Distanz unverwechselbar. Essbar (mild) ist nur das junge «Hexenei»: weiss, elastisch-prall, eiergross. VOR der Verwendung längs aufschneiden – innen muss eine grünlich-olive Gallertschicht über einer weissen, gallertigen Innenstruktur liegen. Eier mit weiss-lamelligem Anschnitt liegenlassen: das könnte ein junger, tödlicher Knollenblätterpilz (Amanita) sein.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)','f'),
('pluteus_cervinus','Lange Saison von April bis November mit Schwerpunkt im Frühsommer und Herbst; erscheint büschelig bis einzeln einige Tage nach Regen, sobald das Substrat durchfeuchtet ist, und ist weniger temperaturkritisch als Mykorrhizapilze – auch in milderen Phasen aktiv.','Wächst direkt auf dem Substrat, nicht im Mineralboden; bevorzugt feuchtes, morsches Laubholz, ist aber bodenvag bezüglich pH.','Saprobiont auf morschem Laubholz: Baumstümpfe, liegende Stämme, vergrabenes Holz, Sägemehl- und Holzlagerplätze; in Laub- und Mischwäldern, gern an Buche und Pappel.','mittel','Erkennungsmerkmale: anfangs weisse, frei stehende Lamellen, die durch das rosa Sporenpulver bald fleischrosa werden (Sporenabwurf rosabraun), brauner, oft radialfaseriger Hut, Geruch leicht rettichartig, KEIN Ring und KEINE Knolle. Die freien, rosa Lamellen plus Wuchs auf Holz trennen ihn von braunhütigen Risspilzen/Trichterlingen. Wegen der rosa Lamellen unbedingt von jungen, weisslamelligen Knollenblätterpilzen unterscheiden – diese wachsen am Boden und haben Ring und Knolle.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)','f'),
('polyporus_umbellatus','Juni bis September. Sommer- bis Frühherbstpilz; der grosse Büschel erscheint nach warmen, feuchten Perioden mit ergiebigem Sommerregen, oft mehrere Jahre an derselben Stelle aus dem dauerhaften unterirdischen Sklerotium.','Nährstoffreiche, humose Laubwaldböden über dem unterirdischen Sklerotium, meist an Stümpfen und Wurzeln alter Laubbäume.','Schwächeparasit/Saprobiont an den Wurzeln von Eiche, Buche und Hainbuche; der vielhütige Fruchtkörper wächst am Boden direkt aus einem knolligen Sklerotium nahe Stammbasis, Stümpfen oder Totholz alter Laubbäume.','mittel','Nur jung und zart geniessbar, ältere Exemplare werden zäh; gut durchgaren. Kennzeichnend ist der grosse, aus einem gemeinsamen verzweigten Strunk gebildete Büschel vieler kleiner, kreisrunder, in der Mitte genabelter Hütchen mit weissen Poren — eine charakteristische, kaum giftig zu verwechselnde Gestalt. Verwechselbar mit dem ähnlich büscheligen Klapperschwamm (Grifola frondosa, ebenfalls essbar) und dem Riesenporling (Meripilus giganteus, jung essbar, alt magenreizend); tödliche Doppelgänger gibt es nicht, dennoch Bestimmung absichern.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt, Der grosse BLV Pilzführer','f'),
('pseudoclitocybe_cyathiformis','September bis Dezember, bei milder Witterung bis in den Januar. Spätherbst- und Winterpilz; erscheint nach feuchten, kühlen Perioden und übersteht leichte Fröste, oft noch nach den ersten Frösten als einer der letzten Pilze des Jahres.','Frische bis feuchte, humose Wald- und Streuböden sowie morsches, am Boden liegendes Totholz; anspruchslos bezüglich Bodenreaktion.','Saprobiont in Laub-, Nadel- und Mischwald auf Humus, Streu, Holzhäcksel und vermoderndem Totholz, häufig an Wegrändern, Waldwegböschungen und in Parks; oft gesellig.','experte','Nur jung und gut gegart ein geringwertiger Speisepilz; alt zäh. Merkmale: tief trichterförmiger, kaffee- bis graubrauner, hygrophaner Hut, weit am graufaserigen Stiel herablaufende, graue Lamellen. Vorsicht in der Trichterlings-Verwandtschaft: graubraune Trichterlinge und Risspilze ähnlicher Standorte können giftig (muskarinhaltig) sein; nur bei sicherer Bestimmung anhand des typischen graufaserigen Stiels und der herablaufenden Lamellen sammeln, sonst stehen lassen.','123pilze.de; SwissFungi (WSL); DGfM; Laux, Essbare Pilze und ihre giftigen Doppelgaenger','f'),
('ramaria_botrytis','Hauptzeit August–Oktober (vereinzelt bis November); erscheint im Spätsommer/Frühherbst meist 1–2 Wochen nach ergiebigen Regenfällen bei milden 12–18 °C, oft an denselben Stellen wiederkehrend.','Kalkreiche bis basenreiche, eher trockene bis frische Laubwaldböden; meidet stark saure Standorte.','Mykorrhizapilz vor allem mit Rotbuche (Fagus) und Eiche (Quercus) in wärmebegünstigten Laub- und Mischwäldern, häufig an Hängen und Waldrändern auf Kalk.','experte','Blumenkohlartig dicht verzweigte, weisslich-cremefarbene Koralle mit charakteristisch rosa bis weinrot gefärbten Astspitzen und dickem, fleischigem Strunk. Nur jung und fest essbar; ältere, weiche oder bitter werdende Stücke und solche mit gelben Spitzen meiden. Korallen sind generell heikel: einige gelb-/ockerspitzige und bittere Ramaria-Arten wirken abführend. Im Zweifel stehen lassen – ohne sichere Gattungs- und Artkenntnis nicht sammeln.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)','f'),
('rhodocollybia_butyracea','August bis Dezember. Spätsommer- bis Winterpilz; erscheint zahlreich nach feuchten Herbstphasen und Landregen, oft gesellig in der Nadelstreu, und hält bei milder Witterung bis in den Frühwinter durch.','Saure, humose Nadel- und Laubwaldböden; gedeiht auf der Nadel- und Laubstreuauflage, nicht direkt auf Holz.','Streuzersetzer (Saprobiont) vor allem in Fichten- und Nadelwald, auch in Buchen- und Mischwald, auf Nadelstreu und Falllaub; meist truppweise und gesellig.','experte','Nur jung und durchgegart ein geringwertiger Speisepilz, Stiel oft knorpelig-zäh und daher zu entfernen. Kennzeichnend sind der fettig-schmierige, hygrophane, rotbraune bis graubraune Hut mit hellerem Rand, der zur Basis keulig-verdickte, längsfaserige Stiel und der weisse bis blass rosafarbene Sporenstaub. Achtung: bräunliche, kleine Blätterpilze gleicher Standorte umfassen giftige Risspilze (Inocybe, muskarinhaltig) und ungeniessbare Arten — Bestimmung nur mit Sporenpulverfarbe und Stielmerkmalen absichern, im Zweifel stehen lassen.','123pilze.de; SwissFungi (WSL); DGfM; Gerhardt, Der grosse BLV Pilzführer','f'),
('roetling','Sommer bis Spätherbst, etwa Juni–Oktober/November (vereinzelt ab Mai), Schwerpunkt im warmen Sommer und am Übergang Oktober/November. Erscheint einige Tage nach Regen auf warmen, gedüngten Flächen.',NULL,'Saprobiont auf offenen Flächen. Gedüngte, oft beweidete Wiesen und Weiden — besonders Schaf-, Pferde- und Rinderweiden, Feldränder, Nähe von Ställen und Komposthaufen; gelegentlich unter Nadelbäumen (Fichte/Wacholder). Häufig in Hexenringen.','anfaenger',NULL,'Recherche + Faktencheck (mykologische Quellen)','t'),
('rotfuss_hexen_roehrling','Einer der frühen Röhrlinge: ab Mai bis in den Spätherbst, in mehreren Schüben. Fruchtet nach warmem, feuchtem Wetter; Schübe folgen üblicherweise einige Tage bis ~1–2 Wochen nach ergiebigem Regen bei sommerlichen Temperaturen.',NULL,'Mykorrhiza mit Laub- und Nadelbäumen, besonders Buche, Eiche und Fichte. Laub-, Nadel- und Mischwälder; oft im Moos und an etwas saureren, bodensauren Stellen.','anfaenger',NULL,'Recherche + Faktencheck (mykologische Quellen)','t'),
('rotkappe_birken','Sommer bis Herbst, Hauptsaison Juli–Oktober (potenziell Juni–November). Schübe folgen einige Tage bis rund 1–2 Wochen nach ergiebigem Regen bei mildem Wetter; nach feuchten Spätsommer-/Herbstphasen besonders reichlich.',NULL,'Mykorrhiza ausschließlich mit Birken (Betula). Birken in parkartigen Flächen, an Wald- und Wegrändern, in Nadelmischwäldern mit eingestreuten Birken, Moor-/Heidesäumen; in reinen Birkenwäldern eher seltener.','anfaenger',NULL,'Recherche + Faktencheck (mykologische Quellen)','t'),
('russula_aurea','Hauptzeit Juli–September (Randmonate Juni und Oktober); erscheint einzeln einige Tage bis ~1 Woche nach warmen Sommerregen bei 15–20 °C, bevorzugt in wärmeren Phasen wärmebegünstigter Laubwälder.','Eher basenreiche bis neutrale, oft kalkbeeinflusste, frische Laubwaldböden in wärmebegünstigter Lage.','Mykorrhizapilz vor allem mit Rotbuche (Fagus) und Eiche (Quercus), seltener bei Nadelbäumen; in warmen Laub- und Mischwäldern, gern an lichten, südexponierten Hängen.','experte','Auffällig durch leuchtend roten Hut, dazu goldgelb getönte Lamellenschneiden und gelblichen Stiel; Fleisch mild (kein scharfer Geschmack), Sporenpulver dottergelb. Diese Merkmalskombination ist für einen Täubling recht markant, dennoch ist die Gattung Russula artenreich und schwierig. Grundregel zur Sicherheit: nur milde, nicht scharf schmeckende Täublinge gelten als essbar – eine Geschmacksprobe (Stück kauen, ausspucken) hilft, scharfe Arten auszuschliessen. Sichere Artbestimmung nur mit Erfahrung.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)','f'),
('russula_claroflava','Hauptsaison Juli bis Oktober. Erscheint zuverlässig einige Tage nach kräftigen Sommer- und Spätsommer-Regenfällen, wenn die staunassen Moorränder gut durchfeuchtet bleiben. Da er an dauerfeuchte Birkenstandorte gebunden ist, lohnt die Suche besonders in regnerischen, milden Spätsommerwochen.','Saure, nasse bis staunasse, torfige bis humose Böden mit niedrigem pH; meidet Kalk.','Mykorrhiza-Symbiont der Birke (Betula). Typisch an Moorrändern, in Bruch- und Feuchtwäldern, oft direkt im Sphagnum-Torfmoos zwischen Birken. Zeigerstandort: vernässte Birkenbestände, Hochmoorränder.','experte','Kennzeichen: leuchtend chromgelber Hut, weisses Fleisch, das bei Verletzung und im Alter langsam grau bis schwärzlich anläuft, milder Geschmack. Als Täubling (Gattung Russula) nur für Geübte: andere gelbhütige Täublinge sind scharf und ungeniessbar, und Verwechslung mit jungen, noch nicht ausgebreiteten Lamellenpilzen anderer Gattungen ist möglich. Die Speiseprobe (Geschmackstest, ausspucken) und die typische Graufärbung absichern; im Zweifel stehen lassen.','123pilze, SwissFungi, DGfM','f'),
('russula_cyanoxantha','Frühsommer bis Spätherbst, Hauptfruktifikation Juli–Oktober (in manchen Jahren schon Mai/Juni, vereinzelt bis Anfang November). Erscheint einige Tage bis ~1–2 Wochen nach durchdringendem Regen bei warmem Wetter.',NULL,'Mykorrhiza vor allem mit Rotbuche, auch Eiche, seltener Fichte/Weißtanne. Laub- und Mischwälder, besonders Buchen- und Buchen-Tannen-Mischwälder (Waldmeister-Buchenwald). Wegen geringer Ansprüche in sehr vielen Waldtypen anzutreffen.','anfaenger',NULL,'Recherche + Faktencheck (mykologische Quellen)','t'),
('russula_decolorans','Hauptsaison Juli bis Oktober, Schwerpunkt im Spätsommer und Frühherbst. Fruktifiziert wenige Tage nach ergiebigen Regenfällen in feuchten Nadelwald- und Moorrandlagen; ergiebige, kühlere Herbstwochen nach Niederschlag sind am besten.','Saure, feuchte, humose bis torfige Böden über Sand oder Moor; kalkmeidend.','Mykorrhiza mit Kiefer (Pinus) und Fichte (Picea). Typisch in bodensauren Nadelwäldern, an Moorrändern und in feuchten Lagen, oft bei Heidelbeere und Torfmoos als Zeigern.','experte','Kennzeichen: orangeroter bis ziegelroter Hut, ockergelbes Sporenpulver, mildes Fleisch, das beim Altern und nach Schnitt erst grau, dann schwärzlich verfärbt. Als Russula nur für Geübte: rothütige Täublinge umfassen scharfe, ungeniessbare Arten (Verwechslergruppe). Geschmacksprobe (mild?) und die charakteristische Grau-Schwarz-Verfärbung des Fleisches zur Absicherung nutzen; scharf schmeckende Exemplare verwerfen.','123pilze, SwissFungi, DGfM','f'),
('russula_integra','Hauptsaison Juli bis Oktober. Typischer Bergwaldpilz, der nach sommerlichen Gewitterregen und in feuchten Frühherbstphasen erscheint; in höheren Lagen entsprechend etwas später. Suche nach durchfeuchteten, milden Perioden in den Fichten-Tannen-Bergwäldern.','Kalkhaltige bis neutrale, humose, gut durchlüftete Bergwaldböden.','Mykorrhiza mit Fichte (Picea), Tanne (Abies) und Kiefer (Pinus). Typisch in montanen bis subalpinen Nadel- und Bergwäldern auf basenreichem Untergrund.','experte','Kennzeichen: braunroter bis kastanienbrauner Hut, ockergelbes Sporenpulver, milder, nussiger Geschmack, Fleisch verfärbt nicht. Als Täubling (Gattung Russula) nur für Geübte: zahlreiche ähnlich gefärbte Täublinge, darunter scharfe und ungeniessbare Arten. Mit Geschmacksprobe (mild, nicht scharf), Sporenpulverfarbe und Standort absichern; im Zweifel verwerfen.','123pilze, SwissFungi, DGfM','f'),
('russula_nigricans','Hauptsaison Juli bis Oktober. Erscheint nach durchdringenden Sommer- und Herbstregen in Laub- und Nadelwäldern; die robusten Fruchtkörper stehen oft lange und sind auch in trockeneren Phasen noch als alte, geschwärzte Exemplare auffindbar. Junge, feste Pilze nur in feuchten Wochen.','Frische, humose Wald- und Mischwaldböden, von sauer bis neutral, ohne ausgeprägte Standortbindung.','Mykorrhiza mit Buche (Fagus), Fichte (Picea) und Eiche (Quercus). Verbreitet in Laub-, Nadel- und Mischwäldern.','experte','Nur jung und nur als bedingt essbar (gut durchgaren, kann Magen-Darm-Beschwerden verursachen) zu sammeln. Kennzeichen: dickliche, weit auseinanderstehende Lamellen, Fleisch rötet erst, dann schwärzt es; alte Fruchtkörper werden komplett schwarz. Als Russula und wegen der Schwärztäubling-Gruppe nur für Geübte: vom essbaren Schwärztäubling (R. nigricans) sind dünnblättrige, schärfer schmeckende oder roh giftige Verwandte abzugrenzen. Im Zweifel stehen lassen.','123pilze, SwissFungi, DGfM','f'),
('russula_ochroleuca','Hauptsaison Juli bis November, einer der häufigsten und ausdauerndsten Täublinge bis in den Spätherbst. Erscheint zuverlässig nach Regen in Nadel- und Mischwäldern; in milden, feuchten Herbstwochen massenhaft.','Saure, humose Nadel- und Laubwaldböden; kalkmeidend.','Mykorrhiza mit Fichte (Picea), Buche (Fagus) und Eiche (Quercus). Sehr verbreitet in bodensauren Nadel-, Laub- und Mischwäldern.','experte','Nur bedingt essbar bis minderwertig: der Ockertäubling ist leicht schärflich und gilt vielerorts als nicht empfehlenswert, daher kein Anfänger-Speisepilz. Kennzeichen: schmutzig ocker- bis grüngelber Hut, blass cremefarbenes Sporenpulver, mild bis leicht scharf. Als Täubling (Gattung Russula) nur für Geübte: enge Verwandtschaft mit scharfen, ungeniessbaren gelbhütigen Täublingen. Geschmacksprobe durchführen; scharfe Exemplare verwerfen, im Zweifel stehen lassen.','123pilze, SwissFungi, DGfM','f'),
('russula_paludosa','Hauptzeit Juli–Oktober; erscheint nach sommerlichen bis herbstlichen Regenphasen, sobald die feuchten Moorränder durchnässt sind, schubweise bei 12–18 °C – einer der ergiebigeren Speisetäublinge höherer, feuchter Nadelwaldlagen.','Saure, dauerfeuchte bis nasse, torfige Böden; an Moorrändern, Hochmoorrändern und in feuchten Nadelwäldern höherer Lagen.','Mykorrhizapilz mit Kiefer (Pinus) und Fichte (Picea); in Moorwäldern, an Torfmoospolstern und entlang vernässter Nadelwaldsenken, oft bei Heidelbeere und Torfmoos als Zeigern.','experte','Grosser, fester Täubling mit blutrotem bis rosarotem, oft mittig blasserem Hut, weissem Stiel mit zartem Rosaton, cremefarbenen Lamellen und blassgelbem Sporenpulver; Geschmack mild bis höchstens leicht schärflich. Standort (saure Moorränder, Kiefer/Fichte) ist ein gutes Indiz. Auch hier gilt die Täublings-Sicherheitsregel: nur milde Arten verwenden, scharf schmeckende verwerfen. Artbestimmung in der schwierigen Gattung Russula nur mit Erfahrung.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)','f'),
('russula_vesca','Frühsommer bis Herbst, ab Juni; Hauptsaison Juli–September, noch bis Oktober. Schübe folgen einige Tage bis ~1–2 Wochen nach ergiebigem, warmem Regen.',NULL,'Mykorrhiza mit Laub- und Nadelbäumen, besonders Rotbuche, Eiche, Fichte und Kiefer. Laub-, Nadel- und Mischwälder sowie Heiden; oft auf sandigem Boden unter Eichen und Buchen.','anfaenger',NULL,'Recherche + Faktencheck (mykologische Quellen)','t'),
('russula_virescens','Sommer bis Herbst, Juni–Oktober; erscheint einige Tage nach warmen Sommerregen, besonders reichlich in warmen, schwülen Sommern bei milden 15–22 °C. Hauptschub Juli–September.','Bevorzugt eher nährstoffarme, oft leicht saure bis neutrale Böden in warmen Laubwäldern; verträgt auch wärmebegünstigte, trockenere Standorte.','Mykorrhiza-Partner v. a. Eiche, Buche und Hainbuche (selten Nadelbäume); in warmen Laub- und Laubmischwäldern, gern an lichten, sonnigen Stellen wie Waldrändern, Wegböschungen und Lichtungen.','mittel','Auf das typisch spangrüne, feldrig-aufgerissene (kacheliges Muster) Hutoberhäutchen achten — bestes Merkmal. In wärmebegünstigten Eichen-/Buchenwäldern an lichten Stellen suchen, 2–5 Tage nach warmem Sommerregen. Erscheint einzeln bis in kleinen Gruppen, kehrt jährlich an dieselben warmen Hangstandorte zurück.','AWL.ch / Pilzverein Region Baden (pilz-baden.ch) / 123pilzsuche.de / Fundkorb.de — Mykorrhiza Eiche/Buche/Hainbuche, Saison Sommer–Herbst bestätigt','t'),
('russula_xerampelina','Hauptzeit Juli–Oktober mit Schwerpunkt im Spätsommer/Frühherbst; erscheint einige Tage bis ~1 Woche nach ergiebigem Regen bei 12–18 °C, schubweise unter Fichte und Kiefer vom Tiefland bis zur Waldgrenze.','Eher saure, frische bis mässig feuchte Nadelwaldböden; weit verbreitet, vom Tiefland bis in höhere Lagen.','Mykorrhizapilz mit Fichte (Picea abies) und Kiefer (Pinus); in Nadel- und Mischwäldern, häufig im Fichtenmoos und entlang von Waldwegen.','experte','Das namensgebende Hauptmerkmal ist der Heringsgeruch (nach altem Fisch/Krabben), der im Alter und beim Trocknen stärker wird; Hut weinrot bis purpurbraun, Stiel beim Reiben/Altern gilbend bis bräunend, Fleisch mild, Sporenpulver ockergelb. Eine Tüpfelprobe mit Eisensulfat (FeSO4) färbt das Fleisch typisch grünlich – ein gutes Bestätigungsmerkmal. Wie bei allen Täublingen: nur milde, nicht scharfe Exemplare verwenden; sichere Artbestimmung erfordert Erfahrung in der Gattung Russula.','123pilze.de; DGfM-Artporträt; SwissFungi (WSL); Standard-Pilzführer (Laux, Gerhardt)','f'),
('sarcodon_imbricatus','Spätsommer bis Herbst, etwa August–November; fruchtet nach herbstlicher Feuchte und ersten kühleren, regnerischen Phasen. Schübe oft mehrere Jahre am selben Standort.','Saure, eher nährstoffarme Nadelwaldböden; bevorzugt moosige, podsolige Standorte der Hügel- bis Bergstufe.','Mykorrhiza-Partner vor allem Fichte (Picea), auch Tanne/Kiefer; in moosreichen Nadelwäldern der Hügel- und Bergstufe, gern in Fichtenforsten und an moosigen, sauren Stellen.','mittel','In älteren, moosreichen Fichtenwäldern der mittleren bis höheren Lagen suchen, oft truppweise. Markante grobe, dunkle Hutschuppen und Stacheln (statt Lamellen) auf der Hutunterseite sind unverwechselbar. Standorte merken — der Pilz kehrt jahrelang an dieselbe Stelle zurück. Hauptzeit nach den ersten kühl-feuchten Herbsttagen.','Fundkorb.de / AWL.ch / lexikon-pilze.de / pilzkurse.com (Schweiz) — Mykorrhiza Fichte, Saison Spätsommer–Herbst (Aug–Nov) bestätigt','t'),
('schopftintling','Nach Regen von Mai bis Oktober/November; zwei Schübe — Frühjahr (April–Juni) und stärker im Herbst (September–November). Erscheint sehr schnell, oft schon 1–2 Tage nach durchdringendem Regen.','Nährstoffreiche, stickstoffhaltige, oft gestörte oder gedüngte Böden; verträgt verdichtete Erde an Wegrändern, Schuttplätzen und Baustellen.','Saprobiont (kein Mykorrhiza-Partner) auf gedüngten Wiesen, Weiden, Rasen, Parks, Gärten, Wegrändern, Parkplätzen, Straßen- und Waldrändern; typischer Siedlungs-/Kulturlandschaftspilz.','anfaenger','Direkt nach kräftigem Regen suchen — die jungen, noch geschlossenen, weiß-zylindrischen Fruchtkörper erscheinen explosiv über Nacht. Oft in Gruppen oder Hexenringen auf Rasenflächen und Wegrändern. Sehr kurzlebig: zerfließt rasch zu schwarzer Tinte (Autolyse), daher nur ganz junge Exemplare sind brauchbar. Leicht erkennbar durch schopfig-schuppigen Hut.','Allgemein etabliertes mykologisches Wissen (Coprinus comatus): Saprobiont, Siedlungs-/Wiesenpilz, Doppel-Schub Frühjahr+Herbst — plausibel, keine Korrektur nötig','t'),
('semmelstoppelpilz','Spätsommer bis Herbst, August–November (regional bis in den Frühwinter); fruchtet nach feuchter Spätsommer-/Herbstwitterung. Bildet oft Hexenringe und kehrt jährlich an dieselben Stellen zurück.','Bevorzugt etwas kalkhaltige, basenreiche Böden; gedeiht aber auch auf neutralen bis schwach sauren, moosigen Waldböden in Laub- und Nadelwäldern.','Mykorrhiza-Partner Buche, Eiche, Fichte und Tanne; in Laub-, Nadel- und Mischwäldern, gern in moosigen Bereichen und an Wegböschungen.','anfaenger','Im moosigen Unterwuchs von Laub- und Nadelwäldern suchen, oft truppweise oder in Hexenringen. Die weichen, brüchigen Stacheln (statt Lamellen) auf der Hutunterseite sind das sichere, anfängerfreundliche Merkmal — kaum verwechselbar. Standorte merken, da er jährlich wiederkehrt.','Wikipedia / AWL.ch / Fundkorb.de — Mykorrhiza Buche/Fichte/Tanne, kalkhold, Saison Spätsommer–Herbst (Aug–Nov) bestätigt','t'),
('shiitake','In Mitteleuropa praktisch nur kultiviert; kein natürliches Freilandvorkommen. Auf beimpftem Laubholz fruchtet er stammabhängig im Frühjahr oder Herbst bei feucht-mildem Wetter (Fruchtung ~10–20 °C), oft nach Temperatur-/Feuchtereiz.','Kein Bodenpilz (lignikol/holzbewohnend); benötigt feuchtgehaltenes, totes Hartholz als Substrat statt Erdboden.','Wächst auf totem Laubholz, vor allem Eiche, Buche, Edelkastanie (im Ursprung der Shii-Baum/Pasania); in Mitteleuropa auf beimpften Hartholzstämmen oder -dübeln. Wildvorkommen nur in Ostasien.','experte','Kein klassischer Wildsammel-Pilz in der Schweiz — Freilandvorkommen fehlt. In der Praxis nur über eigene Beimpfung von Hartholzstämmen (Eiche/Buche) mit Brut zu ernten. Stämme schattig und feucht lagern, Fruchtung durch Wässern/Kältereiz auslösen. ''experte'' wegen Kultivierungsaufwand statt Bestimmung.','Allgemein etabliertes mykologisches Wissen (Lentinula edodes): lignikol auf Eiche/Buche/Edelkastanie, in Mitteleuropa nur kultiviert, Wildvorkommen Ostasien — plausibel, keine Korrektur nötig','t'),
('sparassis_crispa','Spätsommer bis Herbst, etwa August–November (regional ab Juli, bis Dezember); fruchtet nach feuchter Spätsommerwitterung. Kommt jahrelang am selben Baum wieder.','Kein eigentlicher Bodenpilz — parasitisch/saprob an Kiefern-Wurzelholz; wächst an der Stammbasis lebender oder absterbender Kiefern sowie auf Stümpfen, gern auf sauren Sandböden der Kiefernforste.','Fast ausschließlich an der Stammbasis und über den Wurzeln von Kiefern (selten Fichte/Lärche), auch an Stümpfen und am Boden in unmittelbarer Baumnähe; in Kiefernwäldern und -forsten.','mittel','Gezielt an der Stammbasis und über den Wurzeln älterer Kiefern absuchen — der blumenkohl-/badeschwammartige, ocker-gelbliche Fruchtkörper ist unverwechselbar. Erscheint meist einzeln, aber groß; ein produktiver Baum trägt über Jahre. ''mittel'', weil das Auffinden Standortkenntnis (alte Kiefern) erfordert, die Bestimmung selbst aber einfach ist.','Wikipedia / Fundkorb.de / tintling.com / fungiversum.de — Wirtsbaum Kiefer, Stammbasis-parasit, Saison Aug–Nov bestätigt','t'),
('steinpilz','Frühsommer bis Spätherbst; Hauptzeit Ende August–Oktober. Am besten ca. 5–10 (1–2 Wochen) Tage nach ergiebigem Regen bei mildem Wetter 15–23 °C und nicht zu kalten Nächten; erscheint in Schüben.','Anpassungsfähig auf sauren bis neutralen, eher nährstoffarmen Wald- und Bergböden; gedeiht auf moosigen, durchlässigen Standorten, oft bei Heidelbeer-Unterwuchs.','Mykorrhiza-Partner v. a. Fichte und Buche (auch Kiefer, Tanne, Eiche, Birke); im Bergland mit Fichte, im Flachland mit Buche/Eiche. Sonnige Waldränder, Wegränder und Lichtungen; Moospolster und Heidelbeeren sind gute Zeigerpflanzen.','mittel','5–10 Tage nach ergiebigem warmem Regen suchen, wenn die Nächte noch nicht zu kalt sind. Sonnige Waldränder, Wegböschungen und Lichtungen mit Fichte/Buche absuchen; Moospolster und Heidelbeerkraut sind verlässliche Zeigerpflanzen. Erscheint schubweise — wo einer steht, sind oft mehrere. Der feste, weiße, nicht blauende Schwamm und das helle Stielnetz sind sichere Merkmale.','Allgemein etabliertes mykologisches Wissen (Boletus edulis): Mykorrhiza Fichte/Buche/Kiefer/Eiche, Sommer–Spätherbst, ~1–2 Wochen nach Regen — plausibel, keine Korrektur nötig','t'),
('strobilomyces_strobilaceus','Hauptsaison Juli bis Oktober. Erscheint einzeln und meist nicht häufig einige Tage nach ergiebigen Sommer- und Frühherbstregen in feuchten Laub- und Mischwäldern; warme, durchfeuchtete Spätsommerphasen sind am ergiebigsten.','Frische bis feuchte, humose Wald- und Mischwaldböden, bevorzugt etwas saurer Untergrund.','Mykorrhiza mit Buche, Eiche, Fichte, Tanne und Kiefer. Typisch in feuchten Laub- und Mischwäldern, oft an Wegrändern, Böschungen und in der Krautschicht.','mittel','Unverwechselbares Erkennungsmerkmal: grob abstehend schwarz-graue, schuppig-struppige Hutoberfläche, weisslich-graue Röhren, und das Fleisch verfärbt nach Schnitt erst rötlich, dann schwarz. Nur jung essbar (alt zäh und geschmacklos), gut durchgaren. Aufgrund des charakteristischen Aussehens kaum mit Giftpilzen zu verwechseln; als Röhrling jedoch stets das typische Rot-dann-Schwarz-Verfärben und die struppige Hutoberfläche prüfen.','123pilze, SwissFungi, DGfM, Pilzführer','f'),
('stropharia_rugosoannulata','Hauptzeit Juni und September–November, mit kleinerem Frühschub ab Mai; erscheint schubweise rund 1–2 Wochen nach kräftigem Regen bei mildem Wetter (ca. 12–20 °C). Reagiert stark auf frisch ausgebrachtes Holzhäcksel/Stroh und kann bis zum ersten strengen Frost fruchten.','Nährstoffreiche, humose, eher feuchte Böden; gedeiht bevorzugt auf zersetzendem organischem Material (Holzschnitzel, Stroh, Kompost). Bodenreaktion wenig kritisch (neutral bis leicht sauer), entscheidend ist frisches Häcksel-/Streusubstrat.','Kein Mykorrhizapilz, sondern saprob auf totem Pflanzenmaterial: Holzhäcksel-Beete, Rindenmulch, Strohballen, Komposthaufen, Ruderalstellen und Wegränder. Häufig in Gärten und auf Kulturbeeten (verbreiteter Speise-Kulturpilz).','anfaenger','Gezielt frisch gemulchte Beete, Rindenmulch-Flächen und Strohballen in Gärten/Parks absuchen. Erkennungsmerkmale: kräftiger, fleischiger Fruchtkörper mit rotbraun bis graubraun gefärbtem Hut, weisslich-grauem Stiel und auffallend dickem, oberseits gefurchtem (sternförmig gerieftem) Ring; Lamellen jung blass, im Alter purpur-graubraun durch das Sporenpulver. Verwechslungsarme Art, da kaum giftige Doppelgänger im selben Mulch-Habitat – im Zweifel Sporenpulverfarbe (dunkel purpurbraun) prüfen.','123pilze; DGfM; SwissFungi; gängige Pilzführer (Laux, Gerhardt)','f'),
('suillellus_luridus','Hauptzeit Juli–Oktober (vereinzelt ab Juni); erscheint einige Tage bis ~2 Wochen nach durchdringenden Sommer-/Herbstregen bei warmen Bodentemperaturen (ca. 15–22 °C). Wärmeliebend, daher in milden Lagen früh und schubweise.','Bevorzugt basen-/kalkreiche, eher trockenwarme Böden; meidet stark saure Standorte. Gut drainierte, oft lehmig-kalkige Waldböden.','Mykorrhizapilz an Laubbäumen, v. a. Eiche, Buche, Linde und Hainbuche; auch in Parks, Alleen und an Wegrändern. Zeigerstandort sind kalkreiche, lichte Laub-/Mischwälder.','experte','Wärmebegünstigte Kalk-Laubwälder mit Eiche/Buche/Linde absuchen. Bestimmungsmerkmale: rotes bis orangerotes Röhrenmündungs-Netz nicht – wichtig ist das deutliche rote Netz auf dem Stiel, gelbes Fleisch das beim Anschnitt rasch tiefblau anläuft, sowie meist orangerote Poren. Achtung: bedingt essbar – nur gut durchgegart geniessbar, roh giftig, Alkoholunverträglichkeit möglich. Streng abzugrenzen vom giftigen Satans-Röhrling (Rubroboletus satanas, blasser Hut, schmieriger Geschmack) und anderen rotporigen Röhrlingen; nur für erfahrene Sammler. Verlässlich ist die Bourgeois-Linie (rötlicher Strich zwischen Röhrenboden und Hutfleisch).','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt)','f'),
('suillus_bovinus','Hauptzeit August–Oktober (Randmonate Juni/Juli und November möglich); fruchtet gut 1–2 Wochen nach ergiebigem Regen bei 10–18 °C, oft truppweise und gesellig bis in den Spätherbst.','Saure, sandige, nährstoffarme und meist eher trockene Böden; typisch für podsolige Kiefernstandorte, Heiden und Moorränder.','Mykorrhizapilz fast ausschliesslich mit Kiefer (v. a. Wald-Kiefer); auf sandigen Kiefernwäldern, Heiden und in Moornähe. Häufig vergesellschaftet mit dem Rosenroten Gelbfuss (Gomphidius roseus) als Begleiter.','mittel','In lichten Kiefernwäldern auf Sandboden suchen, gern an Wegrändern und moosigen Stellen. Merkmale: ocker- bis ledergelber, schmieriger Hut, weit herablaufende, grob-eckige, olivgelbe bis bräunliche Poren (nicht fein wie beim Steinpilz), zäh-elastisches Fleisch, das schwach rötlich/bräunlich verfärben kann. Speisewert gering (weicher, im Alter mehliger Pilz) – jung sammeln. Verwechslung v. a. mit anderen Schmierröhrlingen (Suillus); keine gefährlich giftigen Doppelgänger, aber Sandkiefer-Bindung als Bestätigung nutzen.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt)','f'),
('suillus_collinitus','Spätsommer bis Spätherbst, Hauptzeit August–November. Wärmeliebende Kalkart; fruchtet schubweise rund 1–2 Wochen nach ergiebigen Regenphasen bei mild-feuchtem Wetter, oft gesellig in kleinen Trupps. Profitiert von warmen, trockenen Sommern mit gelegentlichen Niederschlägen.','Kalkliebend: gedeiht auf basenreichen, kalkhaltigen, eher trockenen und sandig-mageren Böden. Im Gegensatz zum Körnchen-/Butterpilz an Kalk gebunden.','Mykorrhiza streng an zweinadelige Kiefern (Pinus, v.a. Wald-/Schwarzkiefer) gebunden. In lichten Kiefernwäldern, Föhrenforsten, an grasigen Wegrändern, Böschungen und Trockenrasen auf Kalk. Gerne an warmen, sonnigen, südexponierten Stellen.','mittel','Sicher erkennbar an: schmierig-glänzendem, oft rosa-violett überlaufenem braunem Hut, fehlendem Ring am Stiel (im Gegensatz zum Butterpilz Suillus luteus) und namensgebendem rosaroten Myzelfilz an der Stielbasis. Verwechselbar mit anderen Schmierröhrlingen (Suillus) – diese sind alle ungiftig, aber nur als bedingt essbar einzustufen; die abziehbare Huthaut sollte vor dem Verzehr entfernt werden, da sie leicht abführend wirkt. Keine tödlichen Röhrlings-Doppelgänger in der Schweiz.','Recherche-Angabe (123pilze, SwissFungi, DGfM, Pilzführer) — mykologisch plausibel, Kalk-Kiefern-Bindung + ringloser schmieriger Hut + rosa Basalfilz korrekt.','f'),
('suillus_granulatus','Hauptzeit Juli bis Oktober, einzelne Trupps schon ab Juni. Fruchtet schubweise rund 1 Woche nach ergiebigem Regen bei mildem Wetter (ca. 12-18°C); profitiert von feuchtwarmen Spätsommer-Perioden und kommt oft truppweise in mehreren Schüben.','Bevorzugt kalkhaltige bis neutrale Böden; gedeiht gut auf basenreichen, eher trockenen bis frischen Standorten. Anders als viele Schmierröhrlinge nicht an saure Böden gebunden.','Mykorrhiza mit zweinadeligen Kiefern (Föhre/Pinus). In CH unter Kiefern an Waldrändern, Lichtungen, Wegrändern, in lichten Föhrenwäldern, Parkanlagen und auf Weiden mit Kiefernbestand. Sonnige, warme Stellen bevorzugt.','anfaenger','An warmen, sonnigen Kiefern-Standorten gezielt suchen - Wegränder, Lichtungen und lichte Föhrenbestände nach Regen absuchen. Erscheint truppweise, oft in lockeren Gruppen; nach dem ersten Fund die Umgebung im Umkreis absuchen. Tritt schubweise rund eine Woche nach ergiebigem Regen auf.','Web-Recherche Juni 2026: fungiversum.de, fundkorb.de, pilzmuseum.at, pilz-baden.ch (CH), Wikipedia - Mykorrhiza zweinadelige Kiefer, Juli-Oktober, kalkhaltige Böden bestätigt.','t'),
('suillus_grevillei','Juni bis November, Sammelschwerpunkt Juli bis Oktober (witterungsabhängig). Erscheint zuverlässig einige Tage nach Niederschlag bei milden Temperaturen; einer der ersten Röhrlinge im Jahr und oft bis in den Spätherbst.','Keine besonderen Bodenansprüche; auf unterschiedlichen Substraten zu finden, solange die Lärche als Partner vorhanden ist. Wächst auf sauren bis kalkhaltigen, frischen Böden.','Obligater Mykorrhiza-Partner der Lärche (Larix), nahezu immer nur dort. In CH unter Europäischer Lärche - Lärchenwälder, lärchenhaltige Mischwälder, Alleen, Parkanlagen, junge Aufforstungen, Waldränder. Selten unter anderen Lärchen/Douglasie.','anfaenger','Strikt an Lärchen gebunden - erst die Lärche finden, dann den Pilz: lohnt sich, gezielt Lärchenbestände, Alleen und junge Aufforstungen abzusuchen. Da einer der frühesten Röhrlinge, schon ab Frühsommer kontrollieren. Erscheint einige Tage nach Regen, oft truppweise unter dem Baum.','Web-Recherche Juni 2026: Wikipedia (Gold-Röhrling), fundkorb.de, pilzmuseum.at, tintling.com - obligater Lärchen-Partner, Juni-November, erster Röhrling des Jahres bestätigt.','t'),
('suillus_variegatus','Juli bis November, besonders häufig im Herbst (September-Oktober). Fruchtet nach feuchten Herbstperioden; reagiert auf Regen mit mildem Wetter, oft etwas später in der Saison als andere Schmierröhrlinge.','Bevorzugt magere, saure und sandige Böden. Typisch für nährstoffarme Standorte; auf basenarmen, sauren Sandböden nicht selten.','Mykorrhiza mit zweinadeligen Kiefern (Föhre/Pinus). In CH in Kiefern-/Föhrenwäldern auf sauren Sandböden, Moorrandwäldern, Heideflächen mit Kiefern. Bevorzugt magere, saure Nadelwald-Standorte.','anfaenger','Saure, sandige Kiefernstandorte und Heideflächen mit Föhren bevorzugt absuchen - oft an magereren Stellen als andere Schmierröhrlinge. Etwas später in der Saison erscheinend; nach feuchten Herbstperioden (September-Oktober) am ergiebigsten. Truppweise zwischen Moos und Heidekraut suchen.','Web-Recherche Juni 2026: fundkorb.de, fungiversum.de, LWF-Wissen 57 (Pilze an der Kiefer), pilzbestimmer.de - Kiefer-Mykorrhiza, saure Sandböden, Juli-November mit Herbstschwerpunkt bestätigt.','t'),
('tricholoma_cingulatum','Spätsommer bis in den frühen Winter, Hauptzeit September–November (in milden Lagen bis Dezember). Fruchtet nach Herbstregen bei kühl-feuchter Witterung, meist gesellig in kleinen Gruppen bei seinen Wirtsbäumen.','Bevorzugt feuchte, oft kalkhaltige bis neutrale Böden auf nassen Standorten; an Bach- und Flussufern, in Auböden und feuchten Senken.','Mykorrhiza-Partner von Weide (Salix) und Birke (Betula). In Auwäldern, Parks, an Weiden-/Birkenreihen, Ufergehölzen und feuchten Gebüschen. Eng an das Vorkommen seiner Wirtsbäume in feuchtem Milieu gebunden.','experte','Kennzeichen: grauer, faseriger Hut mit kleinem Buckel, weisse Lamellen, mehliger Geruch und ein deutlicher, häutiger weisser Ring am Stiel (selten bei Erdritterlingen). Wächst nur bei Weide/Birke. ACHTUNG: Die Gattung Tricholoma (Ritterlinge) enthält schwer giftige Arten wie den Tigerritterling (Tricholoma pardinum) sowie den Grünling (T. equestre, Rhabdomyolyse-Verdacht) – die sichere Artbestimmung erfordert Erfahrung. Nur bestimmen, wenn Ring, Standort (Weide/Birke) und Mehlgeruch zweifelsfrei zusammenpassen; im Zweifel stehen lassen.','Recherche-Angabe (123pilze, SwissFungi, DGfM, Pilzführer) — mykologisch plausibel, Salix/Betula-Bindung + beringter Stiel + giftige Gattungs-Doppelgänger korrekt.','f'),
('tricholoma_columbetta','Hauptzeit August–Oktober (bis November in milden Lagen); erscheint einige Tage bis ~2 Wochen nach ergiebigem Spätsommer-/Herbstregen bei 10–16 °C, meist in kleinen Gruppen.','Saure bis schwach saure Sand- und Silikatböden; bevorzugt mässig frische, nährstoffärmere Standorte.','Mykorrhizapilz an Laubbäumen, vor allem Buche und Eiche, in Laub- und Mischwäldern auf Sauerböden. Zeigerstandort sind bodensaure Buchen-/Eichenwälder.','mittel','In bodensauren Buchen-/Eichenwäldern nach rein weissen Ritterlingen suchen. Merkmale: reinweisser, seidig-faseriger, oft glänzender Hut (im Alter teils mit blau-grünlichen oder rötlichen Flecken), weisse Lamellen, mehlig-gurkiger Geruch, milder Geschmack. Abzugrenzen von giftigen weissen Trichterlingen/Risspilzen (Lamellen herablaufend bzw. brauner Sporenstaub) und vom scharf/seifig riechenden Tigerritterling-Umfeld – im Zweifel die seidige Hutoberfläche und der milde Geschmack als Hinweis nutzen.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt)','f'),
('tricholoma_portentosum','Hauptzeit September–November, in milden Wintern bis Dezember/Januar; einer der spätesten Speisepilze. Fruchtet rund 1–2 Wochen nach Herbstregen bei kühlen 5–12 °C und ist relativ frosttolerant.','Saure, sandige bis moosige, nährstoffarme Böden; typisch für podsolige Nadelwaldstandorte.','Mykorrhizapilz mit Nadelbäumen (v. a. Fichte und Kiefer), gelegentlich auch bei Espe/Birke; in moosigen Nadel- und Mischwäldern. Oft halb im Moos oder unter Nadelstreu verborgen.','mittel','Spät im Jahr in moosigen Kiefern-/Fichtenwäldern suchen, häufig nur die graue Hutkuppe aus Moos/Streu ragend. Merkmale: schmutzig-grauer, radialfaseriger (schwarzfaserig streifiger), schmieriger Hut, weissliche bis blassgelbliche Lamellen, im Stiel und Fleisch oft zart gelblicher Ton, milder Geschmack. Abzugrenzen vom giftigen Tiger-Ritterling (Tricholoma pardinum, graue Schuppen, mehliger Geruch, robuster) und vom bitteren Brennenden Ritterling (T. virgatum, spitzgebuckelt, scharf) – mild schmeckend und gelblicher Ton sprechen für portentosum.','123pilze; DGfM; SwissFungi; Pilzführer (Laux, Gerhardt)','f'),
('vascellum_pratense','Sommer bis Spätherbst, Juni–November. Erscheint wenige Tage bis etwa eine Woche nach Regen auf kurzgrasigen Flächen, oft gesellig in Gruppen oder Reihen; in feuchten Sommern besonders zahlreich.','Auf nährstoffreichen bis mageren Wiesen- und Rasenböden; an offene, kurzgrasige, sonnige Standorte gebunden, kein Waldpilz.','Saprobiont (Streuzersetzer) auf offenem Grünland: Wiesen, Weiden, gemähte Rasen, Park- und Sportanlagen, Böschungen. Wächst direkt im kurzen Gras, nicht bei Bäumen.','experte','Essbar nur im jungen Zustand, solange das Fleisch innen rein weiss und fest ist; sobald es gelblich/olivbraun und pulvrig wird, ungeniessbar. WICHTIG: Jeder kugelige weisse Pilz MUSS längs durchgeschnitten werden – ist im Inneren bereits eine Hut-/Stiel-/Lamellen-Anlage erkennbar, handelt es sich um ein potenziell tödliches Wulstlings-Ei (Amanita, z.B. Grüner Knollenblätterpilz), das einem Stäubling-Ei täuschend ähnlich sieht. Nur durchgehend homogen-weisses Inneres ohne jede Struktur ist ein echter Stäubling. Vom giftverdächtigen Kartoffelbovist (Scleroderma, dunkles Inneres) unterscheiden.','Recherche-Angabe (123pilze, SwissFungi, DGfM, Pilzführer) — mykologisch plausibel; HL24-konservativ wegen tödlicher Amanita-Ei-Verwechslung experte.','f'),
('xerocomellus_chrysenteron','Sommer bis Spätherbst, Hauptzeit Juli–Oktober (vereinzelt ab Juni, bis November). Fruchtet zuverlässig einige Tage bis zwei Wochen nach Regenphasen über die ganze Saison verteilt, meist einzeln bis in kleinen Gruppen.','Bevorzugt saure bis neutrale, humose Wald- und Wegrandböden; anspruchslos und weit verbreitet.','Mykorrhiza mit Laub- und Nadelbäumen (Eiche, Buche, Fichte, Kiefer). In Laub-, Nadel- und Mischwäldern, an Waldwegen, Böschungen, Lichtungen und Wegrändern; einer der häufigsten Röhrlinge.','mittel','Erkennbar am bräunlich-olivfarbenen, oft felderig aufreissenden Hut mit rötlich gefärbten Rissen, gelben Poren und der namensgebenden Rotfärbung in der Stielrinde; Fleisch blaut beim Anschnitt schwach. Keine tödlichen Röhrlings-Doppelgänger in der Schweiz. Verwechselbar mit anderen Rotfussröhrlingen (X. pruinatus, Hortiboletus) – alle essbar, aber nur jung und madenfrei sammeln, da das weiche Fleisch rasch matschig wird und häufig vom Goldschimmel (Hypomyces) befallen ist.','Recherche-Angabe (123pilze, SwissFungi, DGfM, Pilzführer) — mykologisch plausibel, felderig-rissiger Hut + rote Stielrinde + saure Böden korrekt.','f'),
('xerocomellus_pruinatus','Spätsommer bis Spätherbst, Hauptzeit Juli/August–November. Etwas spätere und kühletolerantere Saison als der Gemeine Rotfussröhrling; fruchtet nach Regenphasen bei mild-feuchter Witterung, einzeln bis in kleinen Trupps.','Auf sauren, humosen Waldböden; bevorzugt eher etwas frischere, schattige Lagen.','Mykorrhiza vor allem mit Buche, daneben Eiche und Fichte. In Laub- und Mischwäldern, gern auf Buchen-Standorten, an Wegrändern und Lichtungen.','mittel','Vom Gemeinen Rotfussröhrling zu unterscheiden durch den jung bereiften (fein weisslich überpuderten), kräftiger weinrot bis purpurn gefärbten Hut, der weniger felderig aufreisst, und das stärker und rascher blauende Fleisch; junge Röhren leuchtend gelb. Keine tödlichen Röhrlings-Doppelgänger in der Schweiz. Alle Rotfussröhrlinge sind essbar – nur jung, fest und madenfrei verwenden, das Fleisch wird im Alter rasch weich.','Recherche-Angabe (123pilze, SwissFungi, DGfM, Pilzführer) — mykologisch plausibel, bereifter purpurner Hut + Buchen-Bindung + stärkeres Blauen korrekt.','f'),
('xerocomus_subtomentosus','Juli bis Oktober (gelegentlich ab Frühsommer, selten Frühjahr). Erscheint einige Tage nach Regen bei feuchtwarmer Witterung; über die ganze warme Jahreszeit verstreut, mit Schwerpunkt Spätsommer/Herbst.','Wenig wählerisch; auf sauren bis neutralen, frischen Böden. Häufig in krautreichen, eher bodensauren Wäldern, aber breites Standortspektrum.','Mykorrhiza mit Laub- und Nadelbäumen (breites Spektrum). In CH in fast allen Laub- und Mischwäldern, auch Nadelwald, Gärten und Parks. Oft an moosigen, grasigen Stellen, Waldwegrändern und Lichtungen.','anfaenger','Weit verbreitet und wenig standort-wählerisch - in nahezu allen Wäldern möglich. Gezielt an moosigen, grasigen Stellen, Waldwegrändern und Lichtungen suchen. Erscheint einzeln bis verstreut über die ganze warme Jahreszeit, Schwerpunkt Spätsommer/Herbst nach Regen.','Web-Recherche Juni 2026: Wikipedia (Ziegenlippe), fundkorb.de, digital-nature.de, pilz-sammler.de - breites Mykorrhiza-Spektrum Laub- und Nadelbäume, Juli-Oktober bestätigt.','t'),
('zigeunerpilz','Hauptsaison August bis Oktober (von Spätsommer bis Herbst). Fruchtet nach ergiebigen Herbstregen bei kühler werdender Witterung; zeigt erratisches Jahresverhalten - manche Jahre kaum, dann plötzlich Massenvorkommen.','Saure, nährstoffarme und sandige Böden. Typisch für basenarme, magere Standorte sowie Moorrandbereiche; meidet kalkreiche Böden.','Mykorrhiza vor allem mit Fichte und Kiefer (selten Buche). In CH in nährstoffarmen sauren Nadelwäldern, gern bei Heidelbeeren (Vaccinium), in Mooren und Bergnadelwäldern. Charakterpilz magerer, saurer Föhren-/Fichtenstandorte.','mittel','An sauren, mageren Nadelwald-Standorten suchen - besonders dort, wo Heidelbeeren (Vaccinium) wachsen, ein verlässlicher Begleit-Indikator. In Bergnadelwäldern und an Moorrändern lohnend. Wegen erratischem Jahresverhalten gute Stellen über Jahre merken; in Massenjahren sehr ergiebig nach Herbstregen.','Web-Recherche Juni 2026: Wikipedia (Reifpilz), fundkorb.de, pilzmuseum.at, pilzvereinzug.ch (CH), tintling.com - Mykorrhiza Fichte/Kiefer (selten Buche), saure nährstoffarme Böden, Heidelbeer-Begleitung, August-Oktober, erratisches Massenvorkommen bestätigt.','t')
